--

CREATE FUNCTION idosgd.pk_sgd_consultas_calcular_dias_habiles(fecha_inicio date, dias_habiles integer) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
 DECLARE
   VDESC  VARCHAR(200)=NULL;
BEGIN     
    SELECT   TO_CHAR(MAX(FE_DIA),'DD/MM/YYYY') INTO VDESC   FROM ( 
    SELECT ROW_NUMBER() OVER(ORDER BY FE_DIA   ) fila,FE_DIA  
    FROM IDOSGD.sitm_calendario where FE_DIA >= fecha_inicio   AND   IN_DIA='01' 
    ) TB WHERE fila<=dias_habiles+1;
		 
   RETURN(VDESC);
--EXCEPTION WHEN OTHERS THEN
  -- RETURN(VDESC);
END;
$$;


