--
-- TOC entry 441 (class 1255 OID 21401)
-- Name: pk_sgd_descripcion_de_cargo_documento(character varying, character varying); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.pk_sgd_descripcion_de_cargo_documento(pco_dep character varying, pco_emp character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
 DECLARE
   vco_emp_fun varchar(6);
   vde_cargo varchar(200) = ' ';
   vco_cargo_fun varchar(6);
   vde_ti_fun varchar(6);
BEGIN
   BEGIN
      SELECT
        co_empleado co_emp_fun,
        co_cargo co_cargo_fun,
        case coalesce(co_tipo_encargatura,'1') when '1' then ' ' when '4' then '(i)' else '(e)' end de_ti_fun
        INTO
        vco_emp_fun,
        vco_cargo_fun,
        vde_ti_fun
        FROM idosgd.rhtm_dependencia
       WHERE CO_DEPENDENCIA = PCO_DEP;
   EXCEPTION when others then
         vco_emp_fun  := null;
         vco_cargo_fun:= null;
         vde_ti_fun := ' ';
   END;
   if vco_emp_fun is not null and vco_cargo_fun is not null then
      if PCO_EMP <> vco_emp_fun then
          BEGIN
             select cemp_co_cargo
             into vco_cargo_fun
             from idosgd.rhtm_per_empleados
             where cemp_codemp = PCO_EMP;
             if vco_cargo_fun ='0000' then
               vco_cargo_fun := null;
             end if;
          EXCEPTION when others then
              vco_cargo_fun := null;
          END;
          vde_ti_fun := ' ';
      end if;
   end if;
   if vco_cargo_fun is not null then
     BEGIN
       SELECT ccar_descar
         INTO vde_cargo
         FROM idosgd.rhtm_cargos
        WHERE ccar_co_cargo= vco_cargo_fun;
        vde_cargo := vde_cargo || vde_ti_fun;
     EXCEPTION when others then
       vde_cargo := ' ';
     END;
    end if;
   RETURN(vde_cargo);
EXCEPTION WHEN OTHERS THEN
   RETURN(' ');
END;
$$;


ALTER FUNCTION idosgd.pk_sgd_descripcion_de_cargo_documento(pco_dep character varying, pco_emp character varying) OWNER TO postgres;

