--
-- TOC entry 434 (class 1255 OID 21405)
-- Name: pk_sgd_descripcion_de_documento_des(character, character varying, integer); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.pk_sgd_descripcion_de_documento_des(pnu_ann character, pnu_emi character varying, pnu_des integer) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
   V_RET VARCHAR(400);
BEGIN
   IF PNU_DES IS NOT NULL THEN
      BEGIN
         SELECT CASE d.ti_des  WHEN '01' THEN  idosgd.pk_sgd_descripcion_de_dependencia(d.co_dep_des)
                               WHEN '02' THEN  idosgd.pk_sgd_descripcion_de_proveedor(d.nu_ruc_des)
                               WHEN '03' THEN  (SELECT SUBSTR(RTRIM(deapp) || ' ' || RTRIM(deapm) || ' ' || RTRIM(denom), 1, 200)
                                     FROM   tdtx_ani_simil
                                     WHERE  nulem = d.nu_dni_des)
                               WHEN '04' THEN  (SELECT de_ape_pat_otr || ' ' || de_ape_mat_otr || ' ' || de_nom_otr || ' - ' ||de_raz_soc_otr
                                     FROM idosgd.tdtr_otro_origen
                                     WHERE co_otr_ori = d.co_otr_ori_des) END
         INTO   V_RET
         FROM   idosgd.tdtv_destinos d, idosgd.tdtv_remitos c
         WHERE  d.NU_ANN = PNU_ANN
         AND    d.NU_EMI = PNU_EMI
         AND    d.NU_DES = PNU_DES
         AND    c.nu_ann = d.nu_ann
         AND    c.nu_emi = d.nu_emi;
      EXCEPTION WHEN OTHERS THEN
         V_RET:=NULL;
      END;
   ELSE
      BEGIN
         SELECT idosgd.pk_sgd_descripcion_de_dependencia(a.co_dep_emi)
         INTO   V_RET
         FROM   idosgd.tdtv_remitos a
         WHERE  a.NU_ANN = PNU_ANN
         AND    a.NU_EMI = PNU_EMI;
      EXCEPTION WHEN OTHERS THEN
         V_RET:=NULL;
      END;
   END IF;
   RETURN(V_RET);
END;
$$;


ALTER FUNCTION idosgd.pk_sgd_descripcion_de_documento_des(pnu_ann character, pnu_emi character varying, pnu_des integer) OWNER TO postgres;

