--
-- TOC entry 389 (class 1255 OID 21407)
-- Name: pk_sgd_descripcion_de_emi_ref(character, character varying); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.pk_sgd_descripcion_de_emi_ref(pnu_ann character, pnu_emi character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
 DECLARE
   cdesti  VARCHAR(4000) := '';
   ntam int;
   c_envi CURSOR FOR
      SELECT b.ti_emi,
             b.co_dep_emi,
             b.co_emp_emi,
             b.nu_ruc_emi,
             b.nu_dni_emi,
             b.co_otr_ori_emi
      FROM   idosgd.tdtr_referencia a, idosgd.tdtv_remitos b
      WHERE  a.nu_ann_ref = b.nu_ann
      AND    a.nu_emi_ref = b.nu_emi
      AND    a.nu_ann = pnu_ann
      AND    a.nu_emi = pnu_emi
      ORDER  BY a.co_ref;
BEGIN
   FOR c IN c_envi LOOP
      
      IF cdesti <> '' THEN
         cdesti := cdesti || ';' || chr(10);
      END IF;
	

      IF c.ti_emi = '01' THEN
         cdesti := cdesti || idosgd.PK_SGD_DESCRIPCION_DE_DEPENDENCIA(c.co_dep_emi);
      ELSIF c.ti_emi = '02' THEN
         cdesti := cdesti || 'RUC - ' || idosgd.PK_SGD_DESCRIPCION_DE_PROVEEDOR(c.nu_ruc_emi);
      ELSIF c.ti_emi = '03' THEN
         cdesti := cdesti || 'CIUDADANO - ' || idosgd.PK_SGD_DESCRIPCION_ANI_SIMIL(c.nu_dni_emi);
      ELSIF c.ti_emi = '04' THEN
         cdesti := cdesti || 'OTROS - ' ||idosgd.PK_SGD_DESCRIPCION_OTRO_ORIGEN (c.co_otr_ori_emi);
      ELSIF c.ti_emi = '05' THEN
         cdesti := cdesti || idosgd.PK_SGD_DESCRIPCION_DE_NOM_EMP(c.co_emp_emi);
      END IF;
      ntam := length(cdesti);
      if ntam > 1000 then
         exit;
      end if;
   END LOOP;
   RETURN(cdesti);
END;
$$;


