--
-- TOC entry 383 (class 1255 OID 21416)
-- Name: pk_sgd_descripcion_de_sigla_corta(character varying); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.pk_sgd_descripcion_de_sigla_corta(pco_dep character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
 DECLARE
  VDESC  VARCHAR(200)=NULL;
  VPOS INT;
BEGIN
   SELECT DE_SIGLA
   INTO VDESC
   FROM IDOSGD.RHTM_DEPENDENCIA
   WHERE CO_DEPENDENCIA= PCO_DEP;
   VPOS := INSTR(VDESC, '-' ,1, 1)-1 ;
   IF VPOS>0 THEN
      VDESC := SUBSTR(VDESC,1,VPOS);
   END IF;
   RETURN(VDESC);
EXCEPTION WHEN OTHERS THEN
   RETURN(VDESC);
END;
$$;


