--
-- TOC entry 421 (class 1255 OID 21419)
-- Name: pk_sgd_descripcion_fu_dia_mas(timestamp without time zone, integer); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.pk_sgd_descripcion_fu_dia_mas(pdfecini timestamp without time zone, pndias integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
 DECLARE
   dfecini  TIMESTAMP(0) = pdfecini;
   dfecfin  TIMESTAMP(0) ;
   ncontdia INT = 0;
BEGIN
   if pndias > 0 then
      Begin
      select max(fe_dia)
        into dfecfin
      from (
         select  fe_dia
            from idosgd.sitm_calendario
           where fe_dia > pdfecini
             and in_dia = '01'
             order by fe_dia
             limit pndias) as foo;
/*
         select  max(fe_dia)
            into dfecfin
            from sitm_calendario
           where fe_dia > pdfecini
             and in_dia = '01'
             and rownum <= pndias
             order by fe_dia;
*/
      Exception when others then
         dfecfin := dfecini;
      end;
      ncontdia := cast(dfecfin as date) - cast(dfecini as date);
   else
      ncontdia := 0 ;
   end if;
   RETURN(ncontdia);
END;
$$;


ALTER FUNCTION idosgd.pk_sgd_descripcion_fu_dia_mas(pdfecini timestamp without time zone, pndias integer) OWNER TO postgres;

--
-- TOC entry 351 (class 1255 OID 21420)
-- Name: pk_sgd_descripcion_fu_dia_mes(character varying, character varying); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.pk_sgd_descripcion_fu_dia_mes(panio character varying, pmes character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
	ndmes VARCHAR(2);
BEGIN
     IF pmes IN ('01', '03', '05', '07', '08', '10', '12') THEN
        ndmes := '31';
     ELSIF pmes IN ('04', '06', '09', '11') THEN
        ndmes := '30';
     ELSIF pmes = '02' THEN
        IF panio % 4 = 0 THEN
           ndmes := '29';
        ELSE
           ndmes := '28';
        END IF;
     END IF;
     RETURN(ndmes);
  END;
$$;


ALTER FUNCTION idosgd.pk_sgd_descripcion_fu_dia_mes(panio character varying, pmes character varying) OWNER TO postgres;

--
-- TOC entry 339 (class 1255 OID 21421)
-- Name: pk_sgd_descripcion_fu_dia_tra(timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.pk_sgd_descripcion_fu_dia_tra(pdfecini timestamp without time zone, pdfecfin timestamp without time zone) RETURNS integer
    LANGUAGE plpgsql
    AS $$
 DECLARE
   ncontdia INT = 0;
BEGIN
   if pdfecini < pdfecfin then
      begin
         select count(1)
           into ncontdia
           from idosgd.sitm_calendario
          where fe_dia > pdfecini
            and fe_dia <=  pdfecfin
            and IN_DIA = '01';
      exception when others then
         null;
      end;
   elsif pdfecini = pdfecfin then
      ncontdia := 0;
   else
      ncontdia := -1;
   end if;
   RETURN(ncontdia);
END;
$$;


ALTER FUNCTION idosgd.pk_sgd_descripcion_fu_dia_tra(pdfecini timestamp without time zone, pdfecfin timestamp without time zone) OWNER TO postgres;

--
-- TOC entry 342 (class 1255 OID 21422)
-- Name: pk_sgd_descripcion_fu_doc_ane(character, character varying); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.pk_sgd_descripcion_fu_doc_ane(pnu_ann character, pnu_emi character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$
 DECLARE
   v_adj INT;
   v_ref INT;
   v_ret INT = 0;
BEGIN
   BEGIN
      SELECT COUNT(1)
      INTO v_adj
      FROM idosgd.tdtv_anexos
      WHERE nu_emi = pnu_emi
      AND nu_ann = pnu_ann;
   EXCEPTION
      WHEN OTHERS THEN
         v_adj := 0;
   END;
   BEGIN
      SELECT COUNT(1)
      INTO v_ref
      FROM idosgd.tdtr_referencia
      WHERE nu_emi = pnu_emi
      AND nu_ann = pnu_ann;
   EXCEPTION
      WHEN OTHERS THEN
         v_ref := 0;
   END;
   IF v_adj = 0 AND v_ref = 0 THEN
      v_ret := 0;
   ELSE
      v_ret := 1;
   END IF;
   RETURN(v_ret);
END;
$$;


ALTER FUNCTION idosgd.pk_sgd_descripcion_fu_doc_ane(pnu_ann character, pnu_emi character varying) OWNER TO postgres;

