-- Name: pk_sgd_descripcion_fu_iniciales_emp(character varying); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.pk_sgd_descripcion_fu_iniciales_emp(pco_emp character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
 DECLARE
    V_EMP VARCHAR(50)=NULL;
  BEGIN
    BEGIN
      SELECT CASE WHEN strpos(cemp_denom, ' ')>0 THEN substr(cemp_denom, 1, 1) || substr(cemp_denom, strpos(cemp_denom, ' ')+1, 1) || substr(cemp_apepat, 1, 1) || substr(cemp_apemat, 1, 1)
	  ELSE substr(cemp_denom, 1, 1) || substr(cemp_apepat, 1, 1) || substr(cemp_apemat, 1, 1) END iniciales
        INTO V_EMP
        FROM IDOSGD.rhtm_per_empleados
       WHERE cemp_codemp = pco_emp;
  EXCEPTION WHEN OTHERS THEN
	 V_EMP := NULL;
  END;
     RETURN(V_EMP);
  END;
 
$$;


