--
-- TOC entry 360 (class 1255 OID 21432)
-- Name: pk_sgd_descripcion_otro_origen(character varying); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.pk_sgd_descripcion_otro_origen(pco_otr_ori character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
 DECLARE
   VDESC  VARCHAR(500)=NULL;
BEGIN
   SELECT CASE  WHEN A.DE_RAZ_SOC_OTR IS NULL THEN NULL ELSE A.DE_RAZ_SOC_OTR||' - ' END ||
          A.DE_APE_PAT_OTR||' '||A.DE_APE_MAT_OTR||' '||A.DE_NOM_OTR ||
          CASE  WHEN A.CO_TIP_OTR_ORI IS NULL THEN NULL ELSE ' - ' ||COALESCE(B.CELE_DESELE,'   ') ||': '|| A.NU_DOC_OTR_ORI  END
   INTO   VDESC
   FROM   idosgd.TDTR_OTRO_ORIGEN A,
         (SELECT CELE_CODELE, CELE_DESELE
          FROM   idosgd.SI_ELEMENTO
          WHERE  CTAB_CODTAB ='TIP_DOC_IDENT') B
   WHERE  A.CO_TIP_OTR_ORI = B.CELE_CODELE --(+)
   AND    A.CO_OTR_ORI = Pco_otr_ori;
   RETURN(VDESC);
EXCEPTION WHEN OTHERS THEN
   RETURN(VDESC);
END;
$$;


ALTER FUNCTION idosgd.pk_sgd_descripcion_otro_origen(pco_otr_ori character varying) OWNER TO postgres;

--
-- TOC entry 398 (class 1255 OID 21433)
-- Name: pk_sgd_descripcion_ti_co_dep_des(character varying, character varying); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.pk_sgd_descripcion_ti_co_dep_des(pnu_ann character varying, pnu_emi character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
   cdep_desti   VARCHAR(1000) := NULL;
   v_ti_des     VARCHAR;
   v_co_dep_des VARCHAR;
BEGIN
   SELECT ti_des,
             co_dep_des
        INTO v_ti_des,
             v_co_dep_des
        FROM idosgd.tdtv_destinos
       WHERE nu_ann = pnu_ann
         AND nu_emi = pnu_emi;

         IF v_ti_des = '01' THEN
            cdep_desti := v_co_dep_des;
         END IF;
        RETURN(cdep_desti);
EXCEPTION WHEN OTHERS THEN
   RETURN(cdep_desti);
END;
$$;


ALTER FUNCTION idosgd.pk_sgd_descripcion_ti_co_dep_des(pnu_ann character varying, pnu_emi character varying) OWNER TO postgres;

--
-- TOC entry 344 (class 1255 OID 21434)
-- Name: pk_sgd_descripcion_ti_co_dep_des_v(character varying, character varying); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.pk_sgd_descripcion_ti_co_dep_des_v(pnu_ann character varying, pnu_emi character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  cdep_desti VARCHAR(4000) :='';
  c_envi CURSOR FOR
      SELECT DISTINCT co_dep_des, ti_des
        FROM idosgd.tdtv_destinos
       WHERE es_eli = '0'
         AND nu_ann = pnu_ann
         AND nu_emi = pnu_emi
       ORDER BY ti_des;
BEGIN
   FOR c_env IN c_envi LOOP
      IF cdep_desti <> '' THEN
         cdep_desti := cdep_desti || ';' || chr(10);
      END IF;
      IF c_env.ti_des = '01' THEN
         cdep_desti := cdep_desti || c_env.co_dep_des;
      END IF;
   END LOOP;
   RETURN(cdep_desti);
END;
$$;


ALTER FUNCTION idosgd.pk_sgd_descripcion_ti_co_dep_des_v(pnu_ann character varying, pnu_emi character varying) OWNER TO postgres;

