    LANGUAGE plpgsql
    AS $$
DECLARE
   ctides   VARCHAR(1000) := NULL;
   v_ti_des varchar(1000) := NULL;
BEGIN
   SELECT ti_des
        INTO v_ti_des
        FROM idosgd.tdtv_destinos
       WHERE nu_ann = pnu_ann
         AND nu_emi = pnu_emi;
  ctides := v_ti_des;
  RETURN(ctides);
EXCEPTION WHEN OTHERS THEN
  v_ti_des := '00';
   RETURN(v_ti_des);
END;
$$;


