--
-- TOC entry 356 (class 1255 OID 21436)
-- Name: pk_sgd_descripcion_ti_des_emp(character, character varying); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.pk_sgd_descripcion_ti_des_emp(pnu_ann character, pnu_emi character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
 DECLARE
   cdesti           VARCHAR(1000) = NULL;
   v_ti_des         VARCHAR;
   v_co_dep_des     VARCHAR;
   v_co_emp_des     VARCHAR;
   v_nu_ruc_des     VARCHAR;
   v_nu_dni_des     VARCHAR;
   v_co_otr_ori_des VARCHAR;
BEGIN
   BEGIN
      SELECT ti_des, co_dep_des, co_emp_des, nu_ruc_des, nu_dni_des, co_otr_ori_des
      INTO v_ti_des, v_co_dep_des, v_co_emp_des, v_nu_ruc_des, v_nu_dni_des, v_co_otr_ori_des
      FROM idosgd.tdtv_destinos
      WHERE nu_ann = pnu_ann AND nu_emi = pnu_emi;
   EXCEPTION
      WHEN OTHERS THEN
         v_ti_des := '00';
   END;
   IF v_ti_des = '01' THEN
      cdesti := idosgd.PK_SGD_DESCRIPCION_DE_DEPENDENCIA(v_co_dep_des)|| ' - ' || idosgd.PK_SGD_DESCRIPCION_DE_NOM_EMP(v_co_emp_des) ;
   ELSIF v_ti_des = '02' THEN
      cdesti := 'PROVEEDOR - ' ||idosgd.PK_SGD_DESCRIPCION_DE_PROVEEDOR(v_nu_ruc_des) || ' - RUC: ' || v_nu_ruc_des;
   ELSIF v_ti_des = '03' THEN
      cdesti := 'CIUDADANO - ' ||idosgd.PK_SGD_DESCRIPCION_ANI_SIMIL(v_nu_dni_des) || ' - DNI: ' || v_nu_dni_des;
   ELSIF v_ti_des = '04' THEN
      cdesti := 'OTROS - ' ||idosgd.PK_SGD_DESCRIPCION_OTRO_ORIGEN (v_co_otr_ori_des);
   ELSIF v_ti_des = '05' THEN
      cdesti := idosgd.PK_SGD_DESCRIPCION_DE_NOM_EMP(v_co_emp_des) ;
   END IF;
   RETURN(cdesti);
END;
$$;


ALTER FUNCTION idosgd.pk_sgd_descripcion_ti_des_emp(pnu_ann character, pnu_emi character varying) OWNER TO postgres;

--
-- TOC entry 439 (class 1255 OID 21437)
-- Name: pk_sgd_descripcion_ti_des_emp_v(character, character varying); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.pk_sgd_descripcion_ti_des_emp_v(pnu_ann character, pnu_emi character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
 DECLARE
   cdesti VARCHAR(4000) := '';
   ntam int=0;
   c_envi CURSOR FOR 
		SELECT co_dep_des,
	     co_emp_des,
	     ti_des,
	     nu_dni_des,
	     nu_ruc_des,
	     co_otr_ori_des
		FROM   idosgd.tdtv_destinos
		WHERE  es_eli = '0'
		AND    nu_ann = pnu_ann
		AND    nu_emi = pnu_emi
		ORDER  BY ti_des desc, nu_des;
BEGIN
	FOR c_env IN c_envi LOOP	  
	  IF cdesti <> '' THEN
         cdesti := cdesti || ';' || chr(10);
	  ELSE
		cdesti :='';
      END IF;
	  
      IF c_env.ti_des = '01' THEN
         cdesti := cdesti || idosgd.PK_SGD_DESCRIPCION_DE_DEPENDENCIA(c_env.co_dep_des)|| ' - ' || idosgd.PK_SGD_DESCRIPCION_DE_NOM_EMP(c_env.co_emp_des) ;
      ELSIF c_env.ti_des = '02' THEN
         cdesti := cdesti || 'RUC - ' || idosgd.PK_SGD_DESCRIPCION_DE_PROVEEDOR(c_env.nu_ruc_des);
      ELSIF c_env.ti_des = '03' THEN
         cdesti := cdesti || 'CIUDADANO - ' ||idosgd.PK_SGD_DESCRIPCION_ANI_SIMIL(c_env.nu_dni_des);
      ELSIF c_env.ti_des = '04' THEN
         cdesti := cdesti || 'OTROS - ' ||idosgd.PK_SGD_DESCRIPCION_OTRO_ORIGEN (c_env.co_otr_ori_des);
      ELSIF c_env.ti_des = '05' THEN
         cdesti := cdesti || idosgd.PK_SGD_DESCRIPCION_DE_NOM_EMP(c_env.co_emp_des) ;
      END IF;
	  
      ntam := length(cdesti);
      if ntam > 1500 then
         exit;
      end if;
	END LOOP;	
   RETURN(cdesti);
-- EXCEPTION WHEN OTHERS THEN
      --RETURN(cdesti);
END;
$$;


ALTER FUNCTION idosgd.pk_sgd_descripcion_ti_des_emp_v(pnu_ann character, pnu_emi character varying) OWNER TO postgres;

