-- Name: pk_sgd_descripcion_ti_destino(character varying); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.pk_sgd_descripcion_ti_destino(pti_des character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
 DECLARE
   VRET VARCHAR(200)=NULL;
BEGIN
   SELECT CELE_DESELE
   INTO   VRET
   FROM   idosgd.SI_ELEMENTO
   WHERE  CTAB_CODTAB = 'TIP_DESTINO'
   AND    CELE_CODELE = PTI_DES;
   RETURN(VRET);
EXCEPTION WHEN OTHERS THEN
   RETURN(VRET);
END;
$$;


ALTER FUNCTION idosgd.pk_sgd_descripcion_ti_destino(pti_des character varying) OWNER TO postgres;

--
-- TOC entry 379 (class 1255 OID 21441)
-- Name: pk_sgd_descripcion_ti_emi_emp(character, character varying); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.pk_sgd_descripcion_ti_emi_emp(pnu_ann character, pnu_emi character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
 DECLARE
   cdesti           VARCHAR(1000) = NULL;
   v_ti_emi         VARCHAR;
   v_co_dep_emi     VARCHAR;
   v_co_emp_emi     VARCHAR;
   v_nu_ruc_emi     VARCHAR;
   v_nu_dni_emi     VARCHAR;
   v_co_otr_ori_emi VARCHAR;
BEGIN
   SELECT ti_emi,
          co_dep_emi,
          co_emp_emi,
          nu_ruc_emi,
          nu_dni_emi,
          co_otr_ori_emi
   INTO   v_ti_emi,
          v_co_dep_emi,
          v_co_emp_emi,
          v_nu_ruc_emi,
          v_nu_dni_emi,
          v_co_otr_ori_emi
   FROM   IDOSGD.tdtv_remitos
   WHERE  nu_ann = pnu_ann
   AND    nu_emi = pnu_emi;
   IF v_ti_emi = '01' THEN
      cdesti := IDOSGD.PK_SGD_DESCRIPCION_DE_DEPENDENCIA(v_co_dep_emi)|| ' - ' || IDOSGD.PK_SGD_DESCRIPCION_DE_NOM_EMP(v_co_emp_emi) ;
   ELSIF v_ti_emi = '02' THEN
      cdesti := 'PROVEEDOR - ' || IDOSGD.PK_SGD_DESCRIPCION_DE_PROVEEDOR(v_nu_ruc_emi) || ' - RUC: ' || v_nu_ruc_emi;
   ELSIF v_ti_emi = '03' THEN
      cdesti := 'CIUDADANO - ' ||IDOSGD.PK_SGD_DESCRIPCION_ANI_SIMIL(v_nu_dni_emi) || ' - DNI: ' || v_nu_dni_emi;
   ELSIF v_ti_emi = '04' THEN
      cdesti := 'OTROS - ' ||IDOSGD.PK_SGD_DESCRIPCION_OTRO_ORIGEN (v_co_otr_ori_emi);
   ELSIF v_ti_emi = '05' THEN
      cdesti := IDOSGD.PK_SGD_DESCRIPCION_DE_NOM_EMP(v_co_emp_emi) ;
   END IF;
   RETURN(cdesti);
END;
$$;


ALTER FUNCTION idosgd.pk_sgd_descripcion_ti_emi_emp(pnu_ann character, pnu_emi character varying) OWNER TO postgres;

--
-- TOC entry 412 (class 1255 OID 21442)
-- Name: pk_sgd_mensajeria_cal_dif_fechas_habiles(date, date); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.pk_sgd_mensajeria_cal_dif_fechas_habiles(fecha_inicio date, fecha_fin date) RETURNS integer
    LANGUAGE plpgsql
    AS $$
 DECLARE
   VDESC  INT=0;
BEGIN     
     IF fecha_fin >= fecha_inicio THEN    
         SELECT COUNT(1) INTO VDESC FROM IDOSGD.sitm_calendario where (FE_DIA BETWEEN FECHA_INICIO and fecha_fin) AND  IN_DIA='01' ;
         
         RETURN VDESC;
     ELSE
     	RETURN 0;
     END IF;
	   
--EXCEPTION WHEN OTHERS THEN
  -- RETURN(VDESC);
END;
$$;


ALTER FUNCTION idosgd.pk_sgd_mensajeria_cal_dif_fechas_habiles(fecha_inicio date, fecha_fin date) OWNER TO postgres;

--
-- TOC entry 443 (class 1255 OID 21443)
-- Name: pk_sgd_mensajeria_delmsj(character varying, character varying, integer, integer); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.pk_sgd_mensajeria_delmsj(pnu_ann character varying, pnu_emi character varying, pnu_des integer, pnu_msj integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
--*************************************************************************************************
-- Nombre         : pk_sgd_mensajeria_delmsj
-- Autor          : wcondori
-- Version         : 1.0
-- Descripcion    : Procedimiento ACTUALIZAR.
-- Requerimientos :
-- Comentarios DBA:
-- Fecha       Modificado por  Revisado por    Visado por      Descripcion del Cambio
-- ==========  ==============  ==============  ==============  ==================================
--*************************************************************************************************
DECLARE pcan integer;
  BEGIN
            
		      UPDATE IDOSGD.tdtv_destinos
			 SET Nu_msj=null,fec_enviomsj=null,es_doc_rec='1'
			 WHERE nu_emi = pnu_emi AND nu_ann = pnu_ann AND nu_des=pnu_des AND nu_msj=pnu_msj;
			 
			 SELECT   COUNT(1) into pcan    
					FROM IDOSGD.tdtv_destinos  WHERE nu_emi = pnu_emi AND nu_ann = pnu_ann
					 AND nu_msj IS NOT NULL;

		  IF @pcan=0 THEN 
		    
		     UPDATE IDOSGD.TDTV_REMITOS SET DOC_ESTADO_MSJ='1' WHERE nu_emi = pnu_emi AND nu_ann = pnu_ann;
		    
		  ELSE
		    UPDATE IDOSGD.TDTV_REMITOS SET DOC_ESTADO_MSJ='3' WHERE nu_emi = pnu_emi AND nu_ann = pnu_ann;
		   
		  END IF;
	 RETURN(0);
  EXCEPTION
    WHEN OTHERS THEN
       NULL;
  END;
$$;


ALTER FUNCTION idosgd.pk_sgd_mensajeria_delmsj(pnu_ann character varying, pnu_emi character varying, pnu_des integer, pnu_msj integer) OWNER TO postgres;

