--
-- TOC entry 396 (class 1255 OID 21445)
-- Name: pk_sgd_mensajeria_descargamsj(character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.pk_sgd_mensajeria_descargamsj(pnu_ann character varying, pnu_emi character varying, pnu_des character varying, pnu_msj character varying, pfechaent character varying, phoraent character varying, pfechadev character varying, phoradev character varying, pob_msj character varying, pmo_msj_dev character varying, pes_pen_msj character varying, pes_pen_dev character varying, pest character varying, pnro_guia_devolucion character varying, pfepladev character varying, pnu_acta_vis1 character varying, pnu_acta_vis2 character varying, pfe_acta_vis1 character varying, pfe_acta_vis2 character varying, pes_acta1_msj character varying, pes_acta2_msj character varying, pco_usuario character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$
--*************************************************************************************************
-- Nombre         : pk_sgd_mensajeria_descargamsj
-- Autor          : WCONDORI
-- Version         : 1.0
-- Descripcion    : Procedimiento ACTUALIZAR.
-- Requerimientos :
-- Comentarios DBA:
-- Fecha       Modificado por  Revisado por    Visado por      Descripcion del Cambio
-- ==========  ==============  ==============  ==============  ==================================
--*************************************************************************************************
DECLARE pcan integer;
pExisteActa1  integer;
pExisteActa2  integer;
 BEGIN
            
		     
			 
	 BEGIN

    --IF pest ='3' THEN
   
         UPDATE IDOSGD.tdtv_destinos
			 SET ob_msj=pob_msj,
			 mo_msj_dev=pmo_msj_dev,
			    es_pen_msj=pes_pen_msj,
			    fe_ent_msj=to_date(pfechaent,'DD/MM/YYYY'),
			    es_pen_dev=pes_pen_dev,
			    fe_dev_msj=to_date(pfechadev,'DD/MM/YYYY'), 
			    es_doc_rec=pest,
			    nro_guia_devolucion=pnro_guia_devolucion,
			    ho_dev_msj=to_date(phoradev,'DD/MM/YYYY'),  
			    ho_ent_msj=to_date(phoraent,'DD/MM/YYYY'),  
			    fe_pla_dev=to_date(pfepladev,'DD/MM/YYYY')
			 WHERE nu_emi = pnu_emi AND nu_ann = pnu_ann AND nu_des::text=pnu_des AND nu_msj::text=pnu_msj;
			 
         
        SELECT COUNT(1)
          INTO pExisteActa1
          FROM IDOSGD.TD_DET_MENSAJERIA
         WHERE nu_emi = pnu_emi
           AND nu_ann = pnu_ann
           AND nu_des::text = pnu_des
           AND nu_acta = pnu_Acta_Vis1;
        
        SELECT COUNT(1)
          INTO pExisteActa2
          FROM IDOSGD.TD_DET_MENSAJERIA
         WHERE nu_emi = pnu_emi
           AND nu_ann = pnu_ann
           AND nu_des::text = pnu_des
           AND nu_acta = pnu_Acta_Vis2;

                 
	   IF pfe_Acta_Vis2<>' ' THEN 			 
         IF pExisteActa2=0 THEN                 
                 INSERT INTO IDOSGD.TD_DET_MENSAJERIA 
                 (NU_ANN,NU_EMI,NU_DES ,NU_ACTA ,FEC_NOT_ACTA,ES_NOT_ACTA,DE_OBS_MSJ,DE_RUT_ORI,
                      CO_USE_CRE ,FE_USE_CRE) 
                  VALUES(pnu_ann,pnu_emi,CAST(pnu_des AS INT),pnu_Acta_Vis2,to_date(pfe_Acta_Vis2,'DD/MM/YYYY HH:MI:SS') ,pes_Acta2_msj,'','',pco_usuario ,now());
           
          ELSE
               UPDATE IDOSGD.TD_DET_MENSAJERIA  
               set FEC_NOT_ACTA=to_date(pfe_Acta_Vis2,'DD/MM/YYYY HH:MI:SS') 
                    ,ES_NOT_ACTA=pes_Acta2_msj           
                    ,CO_USE_MOD= pco_usuario
                    ,FE_USE_MOD= now()
               WHERE nu_emi = pnu_emi
               AND nu_ann = pnu_ann
               AND nu_des::text = pnu_des
               AND nu_acta = pnu_Acta_Vis2;
          END IF;
       END IF;   
          IF pExisteActa1=0 THEN                 
                 INSERT INTO IDOSGD.TD_DET_MENSAJERIA  
                 (NU_ANN,NU_EMI,NU_DES ,NU_ACTA ,FEC_NOT_ACTA,ES_NOT_ACTA,DE_OBS_MSJ,DE_RUT_ORI,
                      CO_USE_CRE ,FE_USE_CRE) 
                  VALUES(pnu_ann,pnu_emi,cast(pnu_des as int),pnu_Acta_Vis1,to_date(pfe_Acta_Vis1,'DD/MM/YYYY HH:MI:SS'),pes_Acta1_msj,'','',pco_usuario ,now());
           
          ELSE
               UPDATE IDOSGD.TD_DET_MENSAJERIA  
               set FEC_NOT_ACTA=to_date(pfe_Acta_Vis1,'DD/MM/YYYY HH:MI:SS') 
                    ,ES_NOT_ACTA=pes_Acta1_msj           
                    ,CO_USE_MOD= pco_usuario
                    ,FE_USE_MOD= now()
               WHERE nu_emi = pnu_emi
               AND nu_ann = pnu_ann
               AND nu_des::text = pnu_des
               AND nu_acta = pnu_Acta_Vis1;
          END IF;
 

		EXCEPTION
		 WHEN OTHERS THEN 
	 END;
  
			 
			 
			 SELECT   COUNT(1) into pcan    
					FROM IDOSGD.tdtv_destinos  WHERE nu_emi = pnu_emi
					 AND nu_ann = pnu_ann AND es_doc_rec NOT IN('3','4');

		  IF @pcan=0 THEN 
		    
		     UPDATE IDOSGD.TDTV_REMITOS SET DOC_ESTADO_MSJ='5' WHERE nu_emi = pnu_emi AND nu_ann = pnu_ann;
		    
		  ELSE
		    UPDATE IDOSGD.TDTV_REMITOS SET DOC_ESTADO_MSJ='4' WHERE nu_emi = pnu_emi AND nu_ann = pnu_ann;
		   
		  END IF;
	 RETURN(0);
  EXCEPTION
    WHEN OTHERS THEN
       NULL;
 END;
$$;


ALTER FUNCTION idosgd.pk_sgd_mensajeria_descargamsj(pnu_ann character varying, pnu_emi character varying, pnu_des character varying, pnu_msj character varying, pfechaent character varying, phoraent character varying, pfechadev character varying, phoradev character varying, pob_msj character varying, pmo_msj_dev character varying, pes_pen_msj character varying, pes_pen_dev character varying, pest character varying, pnro_guia_devolucion character varying, pfepladev character varying, pnu_acta_vis1 character varying, pnu_acta_vis2 character varying, pfe_acta_vis1 character varying, pfe_acta_vis2 character varying, pes_acta1_msj character varying, pes_acta2_msj character varying, pco_usuario character varying) OWNER TO postgres;

--
-- TOC entry 345 (class 1255 OID 21446)
-- Name: pk_sgd_mensajeria_revmsj(character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.pk_sgd_mensajeria_revmsj(pnu_ann character varying, pnu_emi character varying, pnu_des character varying, pnu_msj character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$
--*************************************************************************************************
-- Nombre         : pk_sgd_mensajeria_delmsj
-- Autor          : wcondori
-- Version         : 1.0
-- Descripcion    : Procedimiento ACTUALIZAR.
-- Requerimientos :
-- Comentarios DBA:
-- Fecha       Modificado por  Revisado por    Visado por      Descripcion del Cambio
-- ==========  ==============  ==============  ==============  ==================================
--*************************************************************************************************
DECLARE pcan integer;
estado varchar(20);
  BEGIN
            SELECT es_doc_emi into estado FROM IDOSGD.tdtv_remitos  WHERE nu_emi = pnu_emi  AND nu_ann = pnu_ann ;
	   if estado<>'4' then 
		UPDATE IDOSGD.tdtv_destinos
			 SET ES_DOC_REC='2',MO_MSJ_DEV=null,OB_MSJ=null,FE_ENT_MSJ=null,HO_ENT_MSJ=null,
				FE_DEV_MSJ=null,HO_DEV_MSJ=null,ES_PEN_MSJ=null,FEC_FINMSJ=null,FE_PLA_DEV=null,ES_PEN_DEV=null
			 WHERE nu_emi = pnu_emi AND nu_ann = pnu_ann AND nu_des::text=pnu_des AND nu_msj::text=pnu_msj;
			 
			 SELECT   COUNT(1) into pcan    
					FROM IDOSGD.tdtv_destinos  WHERE nu_emi = pnu_emi
					 AND nu_ann = pnu_ann AND es_doc_rec NOT IN('3','4');

		  DELETE FROM IDOSGD.TDTV_ANEXOS WHERE NU_ANN=pnu_ann AND NU_EMI=pnu_emi AND NU_DES::text=pnu_des;
		  IF @pcan=0 THEN 
		    
		     UPDATE IDOSGD.TDTV_REMITOS SET DOC_ESTADO_MSJ='1' WHERE nu_emi = pnu_emi AND nu_ann = pnu_ann;
		    
		  ELSE
		    UPDATE IDOSGD.TDTV_REMITOS SET DOC_ESTADO_MSJ='3' WHERE nu_emi = pnu_emi AND nu_ann = pnu_ann;
		   
		  END IF;
	   end if;
            		      
	 RETURN(0);
  EXCEPTION
    WHEN OTHERS THEN
       NULL;
  END;
$$;


ALTER FUNCTION idosgd.pk_sgd_mensajeria_revmsj(pnu_ann character varying, pnu_emi character varying, pnu_des character varying, pnu_msj character varying) OWNER TO postgres;

--
-- TOC entry 346 (class 1255 OID 21447)
-- Name: pk_sgd_mesa_virtual(character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.pk_sgd_mesa_virtual(p_cousemod character varying, p_depdes character varying, p_nomdes character varying, p_cardes character varying, p_nuann character varying, p_nuemi character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    psidemiext INT;
	psiddocext INT;
	psiddocpri INT;
	prucentrec VARCHAR(500);
	pnomentrec VARCHAR(200);
	puniorgemi VARCHAR(200);
	pvnomentemi VARCHAR(200);
	pccodtipdoc VARCHAR(100);
	pvnumdoc VARCHAR(100);
	pdfecdoc timestamp without time zone;
	pvuniorgdst VARCHAR(500);
	pvnomdst VARCHAR(500);
	pvnomcardst VARCHAR(500);
	pvasu VARCHAR(500);
	psnumanx VARCHAR(10); 
	psnumfol VARCHAR(10);
	pcodepemi VARCHAR(200);
	pcempnudni VARCHAR(100);
	ptienvmsj VARCHAR (1);
	pvcuo VARCHAR(10);
	pconta INT;

BEGIN
    
	SELECT COALESCE(TI_ENV_MSJ,TI_ENV_MSJ,'3')
          INTO PTIENVMSJ
      FROM idosgd.tdtv_remitos WHERE NU_ANN=P_NUANN AND NU_EMI=P_NUEMI;
	IF PTIENVMSJ <> '2' THEN  
		UPDATE idosgd.tdtv_remitos 
          SET CO_USE_MOD=P_COUSEMOD
           ,FE_USE_MOD=now() 
           ,FE_EMI=now()
           ,TI_ENV_MSJ='2'
           WHERE NU_ANN=P_NUANN AND NU_EMI=P_NUEMI;
           
          UPDATE idosgd.TDTV_DESTINOS
          SET DE_DEP_DES=P_DEPDES
              ,DE_NOM_DES=P_NOMDES
              ,DE_CAR_DES=P_CARDES
          WHERE NU_ANN=P_NUANN AND NU_EMI=P_NUEMI AND NU_DES='1';
         
          SELECT NU_RUC_DES,DE_DEP_DES,DE_NOM_DES,DE_CAR_DES
                INTO PRUCENTREC,PVUNIORGDST,PVNOMDST,PVNOMCARDST
          FROM idosgd.TDTV_DESTINOS WHERE NU_ANN=P_NUANN AND NU_EMI=P_NUEMI AND NU_DES='1';
          
          SELECT CPRO_RAZSOC
                INTO PNOMENTREC
          FROM idosgd.LG_PRO_PROVEEDOR WHERE CPRO_RUC=PRUCENTREC;        
          
          SELECT D.DE_DEPENDENCIA,R.CO_DEP_EMI,(SELECT CEMP_NU_DNI FROM idosgd.RHTM_PER_EMPLEADOS WHERE CEMP_CODEMP=R.CO_EMP_EMI)
                INTO PUNIORGEMI,PCODEPEMI,PCEMPNUDNI
          FROM idosgd.RHTM_DEPENDENCIA D INNER JOIN idosgd.TDTV_REMITOS R ON D.CO_DEPENDENCIA=R.CO_DEP_EMI 
		  WHERE R.NU_ANN=P_NUANN AND R.NU_EMI=P_NUEMI;
          
          SELECT DE_PAR
                INTO PVNOMENTEMI
          FROM idosgd.TDTR_PARAMETROS WHERE CO_PAR='RAZONSOCIAL_INSTITUCION';
          
          SELECT CIDTIPDOC
                INTO PCCODTIPDOC
          FROM idosgd.IOTDTX_TIPO_DOCUMENTO 
		  WHERE CDOC_TIPDOC=(SELECT CO_TIP_DOC_ADM FROM  idosgd.TDTV_REMITOS  
							 WHERE NU_ANN=P_NUANN AND NU_EMI=P_NUEMI);
     
         SELECT  NU_DOC_EMI||'-'||NU_ANN||'-'||(SELECT DE_PAR FROM idosgd.TDTR_PARAMETROS WHERE CO_PAR = 'DE_INSTITUCION')
		 ||'-'||DE_DOC_SIG,FE_EMI,DE_ASU,COALESCE(NU_FOL,'1') INTO PVNUMDOC,PDFECDOC,PVASU,PSNUMFOL 
		 FROM  idosgd.TDTV_REMITOS  WHERE NU_ANN=P_NUANN AND NU_EMI=P_NUEMI;
         
         ---AUTOGENERAR CODIGO        
         SELECT nextval('idosgd.sec_iotdtc_despacho') INTO PSIDEMIEXT ;
        
       SELECT COUNT(1) INTO PCONTA FROM idosgd.IOTDTC_DESPACHO 
       WHERE VANIOREGSTD = P_NUANN AND 
         VNUMREGSTD = P_NUEMI AND 
         CFLGEST = 'O';
       
       IF PCONTA = 1 then
        SELECT VCUO INTO PVCUO
         FROM idosgd.IOTDTC_DESPACHO 
         WHERE VANIOREGSTD = P_NUANN AND 
         VNUMREGSTD = P_NUEMI AND 
         CFLGEST = 'O';
         
         UPDATE idosgd.IOTDTC_DESPACHO
            SET CFLGEST = 'S'
         WHERE VANIOREGSTD = P_NUANN AND 
           VNUMREGSTD = P_NUEMI AND 
           CFLGEST = 'O' AND
           VCUO = PVCUO ;
		   
	END IF;
	
	  INSERT INTO idosgd.IOTDTC_DESPACHO(SIDEMIEXT,VNUMREGSTD,VANIOREGSTD,VUNIORGREM,VRUCENTREC,VNOMENTREC,CFLGEST,VUSUREG,DFECREG,VCODUNIORGREM,CTIPDOCIDEREM,VNUMDOCIDEREM,VCUOREF)
         VALUES (PSIDEMIEXT,P_NUEMI,P_NUANN,PUNIORGEMI,PRUCENTREC,PNOMENTREC,'P',P_COUSEMOD,now(),PCODEPEMI,'1',PCEMPNUDNI,PVCUO); 
        
          ---AUTOGENERAR CODIGO         
          SELECT nextval('idosgd.sec_iotdtm_doc_externo')   INTO PSIDDOCEXT ;
           
         SELECT COUNT(1)
                INTO PSNUMANX
         FROM idosgd.TDTV_ANEXOS  WHERE NU_ANN=P_NUANN AND NU_EMI=P_NUEMI AND TI_PUBLIC = '1';
         
         
         INSERT INTO idosgd.IOTDTM_DOC_EXTERNO(SIDDOCEXT,VNOMENTEMI,CCODTIPDOC,VNUMDOC,DFECDOC,VUNIORGDST,VNOMDST,VNOMCARDST,VASU,SNUMANX, SNUMFOL,VURLDOCANX,SIDEMIEXT)
         VALUES (PSIDDOCEXT,PVNOMENTEMI,PCCODTIPDOC,PVNUMDOC,PDFECDOC,PVUNIORGDST,PVNOMDST,PVNOMCARDST,PVASU,TO_NUMBER(PSNUMANX,'9G999g999'),TO_NUMBER(PSNUMFOL,'9G999g999')
				 ,(SELECT DE_PAR FROM idosgd.TDTR_PARAMETROS WHERE CO_PAR='URL_WEB_DESC_ANEXO'),PSIDEMIEXT);   
            
         ---AUTOGENERAR CODIGO          
          SELECT nextval('idosgd.sec_iotdtd_doc_principal')   INTO PSIDDOCPRI ;
		  
         INSERT INTO idosgd.IOTDTD_DOC_PRINCIPAL (SIDDOCPRI,SIDDOCEXT,VNOMDOC,BPDFDOC,CCODEST,DFECREG)
         SELECT PSIDDOCPRI,PSIDDOCEXT,A.NU_ANN||A.NU_EMI||A.TI_EMI||A.CO_TIP_DOC_ADM||A.NU_SEC_EXP||'.PDF',B.BL_DOC,'A',now() 
		 FROM idosgd.TDTV_REMITOS A INNER JOIN idosgd.TDTV_ARCHIVO_DOC B ON A.NU_ANN=B.NU_ANN AND A.NU_EMI=B.NU_EMI 
		 WHERE A.NU_ANN=P_NUANN AND A.NU_EMI=P_NUEMI;
      
         INSERT INTO idosgd.IOTDTD_ANEXO (SIDDOCANX,VNOMDOC,DFECREG,SIDDOCEXT)
         SELECT nextval('idosgd.sec_iotdtd_anexo') ,DE_DET,now(),PSIDDOCEXT FROM idosgd.TDTV_ANEXOS 
		 WHERE NU_ANN=P_NUANN AND NU_EMI=P_NUEMI AND TI_PUBLIC = '1';
         

        END IF;
		
		
   return(0);
END;
$$;


