CREATE FUNCTION idosgd.pk_sgd_mesa_virtual_ciudadano(p_tipoper character varying, p_dni character varying, p_pat character varying, p_mat character varying, p_nom character varying, p_ruc character varying, p_raz character varying, p_tipodoc character varying, p_nrodoc character varying, p_asu character varying, p_arc character varying, p_arcdat bytea, p_dir character varying, p_folio character varying, p_correo character varying, p_tel character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE pcodnuemi varchar(20);
DECLARE  pcodexp varchar(20);
DECLARE  pnexp varchar(20);
DECLARE  pncexp varchar(20);
DECLARE  pnc bigint;
DECLARE  pvnom varchar(150);
DECLARE  ptot int;
DECLARE  pvdni varchar(20);
DECLARE  ptotp int;
DECLARE  pp_res_remitos int;
DECLARE  pp_hora_inicio varchar(10);
DECLARE  pp_hora_fin varchar(10);
DECLARE  pCORRELATIVO_EXP bigint;
DECLARE  pCOD_DEP_MP VARCHAR(10)='11811';
DECLARE  pCOD_DEP_MP_ORIGEN_REG VARCHAR(10)='11811';
DECLARE  pCOD_EMP_EMI_ORIGEN_REG VARCHAR(10)='00000';
DECLARE  pORIGEN_REGISTRO VARCHAR(5)='06' ; -- ORIGEN DE REGISTRO -> CODIGO  MESA DE PARTE DIGITAL CIUDADANO
declare pcodnuemiG bigint=0;
DECLARE presultado VARCHAR(500)='';
DECLARE PCCLAVE VARCHAR(10);
BEGIN

begin --try

			select count(1) INTO ptot from IDOSGD.tdtx_ani_simil where NULEM=p_dni;  
			 
            if (ptot=0) THEN
			 
                insert into IDOSGD.tdtx_ani_simil(NULEM,DEAPP,DEAPM,DENOM,DEDOMICIL,DEEMAIL,DETELEFO)
                values(p_dni,p_pat,p_mat,p_nom,p_dir,p_correo,p_tel);  
				 
            END IF; 
			
    pvnom:=trim(p_pat) || ' ' || trim(p_mat) || ' ' || trim(p_nom);
	
	---AUTOGENERAR CODIGO          
   
	pcodnuemiG := (SELECT nextval('idosgd.sec_remitos_nu_emi') )  ;
	
	pcodnuemi:= (SELECT  RIGHT('0000000000' || (pcodnuemiG)::text , 10)) ;	  
	 
	select  RIGHT('0000000000' || (COALESCE(MAX(CAST(nu_sec_exp AS INTEGER)),0)+1)::text, 10)	INTO pcodexp
	from IDOSGD.TDTC_EXPEDIENTE  WHERE NU_ANN_EXP=TO_CHAR(now(), 'YYYY');
	 
	 select COALESCE(MAX(CAST(NU_CORR_EXP AS INTEGER)), 0) + 1 INTO pCORRELATIVO_EXP
		from IDOSGD.TDTC_EXPEDIENTE WHERE NU_ANN_EXP=TO_CHAR(now(), 'YYYY') and
		co_dep_exp=pCOD_DEP_MP AND  co_gru='3'; 
	 
	 select TO_CHAR(now(),'YYYY') ||'-'|| RIGHT('0000000' || COALESCE(pCORRELATIVO_EXP::text,''), 7) INTO pnexp;	
	 
     select RIGHT('0000000' || COALESCE(pCORRELATIVO_EXP::text,''),7) INTO pncexp	 ; 	
	 SELECT  lpad(floor(random() * 10000)::text, 4, '0') AS nrohistoria_etiqueta INTO PCCLAVE ;
     pnc := pCORRELATIVO_EXP; 
	insert into IDOSGD.TDTC_EXPEDIENTE(NU_ANN_EXP,NU_SEC_EXP,CO_DEP_EXP,NU_EXPEDIENTE,NU_CORR_EXP,FE_EXP,CO_GRU,CCOD_TIPO_EXP,US_CREA_AUDI,FE_CREA_AUDI,CCLAVE)
		VALUES(TO_CHAR(now(), 'YYYY'),pcodexp,pCOD_DEP_MP,pnexp,pncexp,now(),'3','20','MPVC',now(),PCCLAVE);
	
	if (p_tipoper='03') then
			pvdni:=p_dni;			 
	 else		 
			 pvdni:=NULL;
	 end if;
 	
	insert into IDOSGD.TDTV_REMITOS(NU_ANN,NU_EMI,TI_EMI,NU_DNI_EMI,NU_RUC_EMI,DE_ASU,FE_EMI,CO_LOC_EMI,FE_USE_CRE,ES_ELI,CO_TIP_DOC_ADM,DE_DOC_SIG,NU_ANN_EXP,
		DE_ORI_EMI,
		REMI_TI_EMI,
		CDIR_REMITE, 
		NU_SEC_EXP,
		NU_COR_EMI,
		CCOD_ORIGING,NU_FOLIOS,ES_DOC_EMI,CO_USE_CRE,CO_USE_MOD,FE_USE_MOD,CO_DEP_EMI,CO_GRU,NU_DIA_ATE,NU_COR_DOC,REMI_NU_DNI_EMI,CO_EMP_EMI,CO_DEP,
		CEXP_CORREOE,CTELEFONO,NU_DET_EXP,CO_EMP_RES )
		VALUES(TO_CHAR(now(), 'YYYY'),pcodnuemi,p_tipoper,pvdni,p_ruc,p_asu,now(),'001',now(),0,p_tipodoc,p_nrodoc,TO_CHAR(now(), 'YYYY'),
		'aaa',
		p_tipoper,
		p_dir,
	    pcodexp,
		pnc,
		pORIGEN_REGISTRO,cast(p_folio as double precision),'5', 'ADMIN','ADMIN',now(),pCOD_DEP_MP,3,0,pnc,p_dni,pCOD_EMP_EMI_ORIGEN_REG,pCOD_DEP_MP_ORIGEN_REG,p_correo,p_tel,'1'
			   ,pCOD_EMP_EMI_ORIGEN_REG);
	
	  insert into IDOSGD.TDTV_ARCHIVO_DOC(NU_ANN,NU_EMI,BL_DOC,DE_RUTA_ORIGEN)
		VALUES(TO_CHAR(now(),'YYYY'),pcodnuemi,p_arcdat,p_arc);
		
	
	  /* if(select count(1) from P_DOCUMENTO_ADJUNTO)>0 THEN
			INSERT INTO IDOSGD.TDTV_ANEXOS(NU_ANN,NU_EMI,NU_ANE,DE_DET,BL_DOC,DE_RUT_ORI) 
			Select TO_CHAR(now(),'YYYY'), pcodnuemi,inid,vctit,vcarc_da,vctit  FROM P_DOCUMENTO_ADJUNTO;
	   end if;*/
	/*select p_expediente =pnexp;
	select p_anio=TO_CHAR(now(),'YYYY');
	select p_nu_emi= pcodnuemi::text;
	select p_result='OK';*/
	presultado:='OK@'||pnexp||'@'||TO_CHAR(now(),'YYYY')||'@'||(pcodnuemi)::text;
	  -- COMMIT TRANSACTION;
	--end try
    exception -- catch 
	when OTHERS then
	 -- rollback;
	   presultado := 'Error@pk_sgd_mesa_virtual_ciudadano-->'||presultado||SUBSTR(SQLERRM,1,200);
	end;
 
 
	
   return presultado;
END;
$$;


