--
-- TOC entry 408 (class 1255 OID 21455)
-- Name: pk_sgd_tramite_actualiza_esta_u(character, character varying, character varying, timestamp without time zone); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.pk_sgd_tramite_actualiza_esta_u(p_nu_ann character, p_nu_emi character varying, p_dep_ori character varying, p_fecha timestamp without time zone) RETURNS integer
    LANGUAGE plpgsql
    AS $$
 DECLARE
   c_ref CURSOR (v_anno VARCHAR, v_emi VARCHAR, v_dep_ori VARCHAR) FOR
      SELECT e.*,
             coalesce(f.receptor, 'XXX') co_dep_f
      FROM  (SELECT c.nu_ann nu_ann_ref,
                    c.nu_emi nu_emi_ref,
                    c.nu_des nu_des_ref,
                    case b.ti_emi  when '01' then  b.co_dep_emi  when '02' then  b.nu_ruc_emi  when '03' then  b.nu_dni_emi  when '04' then  b.co_otr_ori_emi end emisor,
                    c.co_dep_des,
                    c.es_doc_rec
             FROM ( SELECT nu_ann_ref, nu_emi_ref
                    FROM IDOSGD.tdtr_referencia
                    --START WITH PK_EMI_EMI = v_anno||v_emi
     		    --CONNECT BY PRIOR PK_REF_EMI = PK_EMI_EMI AND LEVEL <= 5
     		    ) a,
                    IDOSGD.tdtv_remitos b,
                    IDOSGD.tdtv_destinos c
             WHERE  a.nu_ann_ref = b.nu_ann
             AND    a.nu_emi_ref = b.nu_emi
             AND    a.nu_ann_ref = c.nu_ann
             AND    a.nu_emi_ref = c.nu_emi
             AND    c.co_dep_des = v_dep_ori) e,
            (SELECT d.nu_ann, d.nu_emi, d.ti_des,
                    case d.ti_des  when '01' then  d.co_dep_des  when '02' then  d.nu_ruc_des  when '03' then  d.nu_dni_des  when '04' then  d.co_otr_ori_des end receptor
             FROM   IDOSGD.tdtv_destinos d
             WHERE  d.nu_ann = v_anno
             AND    d.nu_emi = v_emi) f
      WHERE  e.emisor = f.receptor/*(+)*/;
BEGIN
   FOR d IN c_ref(p_nu_ann, p_nu_emi, p_dep_ori) LOOP
      IF d.co_dep_f = 'XXX' THEN
         IF d.es_doc_rec IN ('1', '5') THEN
            BEGIN
               UPDATE IDOSGD.tdtv_destinos
               SET    es_doc_rec = '4',
                      fe_der_doc = p_fecha
               WHERE  nu_ann = d.nu_ann_ref
               AND    nu_emi = d.nu_emi_ref
               AND    nu_des = d.nu_des_ref;
            END;
         END IF;
      ELSE
         IF d.es_doc_rec IN ('1', '4', '5') THEN
            BEGIN
               --td_pk_tramite_actualiza_estado(d.nu_ann_ref, d.nu_emi_ref, d.nu_des_ref, '2');
               UPDATE IDOSGD.tdtv_destinos
                  SET es_doc_rec = '2',
                      fe_ate_doc = p_fecha
                WHERE nu_ann = d.nu_ann_ref
                  AND nu_emi = d.nu_emi_ref
                  AND nu_des = d.nu_des_ref;
            END;
         END IF;
      END IF;
   END LOOP;
   RETURN(0);
   /* COMMIT; */
END;
$$;


ALTER FUNCTION idosgd.pk_sgd_tramite_actualiza_esta_u(p_nu_ann character, p_nu_emi character varying, p_dep_ori character varying, p_fecha timestamp without time zone) OWNER TO postgres;

--
-- TOC entry 355 (class 1255 OID 21456)
-- Name: pk_sgd_tramite_actualiza_estado(character, character varying, character varying, character varying); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.pk_sgd_tramite_actualiza_estado(pnu_ann character, pnu_emi character varying, pnu_des character varying, pest character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
   vest     SMALLINT;
   pcan     INT;
   vest_rec VARCHAR(1);
   vest_emi VARCHAR(1);
   vestado  VARCHAR(1) = '0';
BEGIN
   SELECT COUNT(1)
     INTO pcan
     FROM IDOSGD.tdtv_destinos
    WHERE nu_emi = pnu_emi
      AND nu_ann = pnu_ann
      AND es_doc_rec <> '9';
   BEGIN
      SELECT es_doc_rec
        INTO vest_rec
        FROM IDOSGD.tdtv_destinos
       WHERE nu_emi = pnu_emi
         AND nu_ann = pnu_ann
         AND nu_des = cast(pnu_des as bigint);
   EXCEPTION
      WHEN OTHERS THEN
         vest_rec := '0';
   END;
   BEGIN
      SELECT es_doc_emi
        INTO vest_emi
        FROM IDOSGD.tdtv_remitos
       WHERE nu_emi = pnu_emi
         AND nu_ann = pnu_ann;
   EXCEPTION
      WHEN no_data_found THEN
         vest_emi := '0';
   END;
   IF vest_rec <> pest THEN
      IF pcan = 1 THEN
         -- CUANDO TIENE UN SOLO DESTINO
         IF pest = '1' THEN
            -- RECIBIDO
            vestado := '2';
         ELSIF pest = '2' THEN
            -- ATENDIDO
            vestado := '3';
         ELSIF pest = '3' THEN
            -- ARCHIVADO
            vestado := '4';
         ELSE
            -- DERIVADO
            vestado := vest_emi;
         END IF;
      ELSIF pcan > 1 THEN
      -- CUANDO TIENE VARIOS DESTINOS
         SELECT COUNT(es_doc_rec) + 1
           INTO vest
          FROM IDOSGD.tdtv_destinos
         WHERE nu_emi = pnu_emi
           AND nu_ann = pnu_ann
           AND es_doc_rec = pest
           AND es_doc_rec <> '9';
         IF pest = '1' AND (vest_rec NOT IN ('6', '3')) THEN
         -- RECIBIDO
            IF vest = pcan THEN
               vestado := '2';
            ELSE
               vestado := '1';
            END IF;
         ELSIF pest = '2' THEN
         -- ATENDIDO
            IF vest = pcan THEN
               vestado := '3';
            ELSE
               vestado := '6';
            END IF;
         ELSE
            vestado := vest_emi;
         END IF;
      END IF;
      BEGIN
         UPDATE IDOSGD.tdtv_remitos
            SET es_doc_emi = vestado
          WHERE nu_emi = pnu_emi
            AND nu_ann = pnu_ann;
      EXCEPTION
         WHEN OTHERS THEN
            NULL;
      END;
   END IF;
   return(0);
END;
$$;


ALTER FUNCTION idosgd.pk_sgd_tramite_actualiza_estado(pnu_ann character, pnu_emi character varying, pnu_des character varying, pest character varying) OWNER TO postgres;

--
