--

CREATE FUNCTION idosgd.pk_sgd_tramite_actualiza_estado_a(pnu_ann character, pnu_emi character varying, pde_ane character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
   vest     SMALLINT;
