   vest_rec VARCHAR(1);
   vest_emi VARCHAR(1);
   vestado  VARCHAR(1) = '0';
BEGIN

	 UPDATE IDOSGD.tdtv_remitos
         SET es_doc_emi = '4'
         WHERE nu_emi = pnu_emi AND nu_ann = pnu_ann;
         
         UPDATE IDOSGD.tdtv_destinos
         SET de_ane = pde_ane,fec_finmsj= CURRENT_TIMESTAMP   
         WHERE nu_emi = pnu_emi AND nu_ann = pnu_ann;
		
		return 1;
		  
END;
$$;


ALTER FUNCTION idosgd.pk_sgd_tramite_actualiza_estado_a(pnu_ann character, pnu_emi character varying, pde_ane character varying) OWNER TO postgres;

--
-- TOC entry 442 (class 1255 OID 21458)
-- Name: pk_sgd_tramite_consulta_tu_expediente(character varying); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.pk_sgd_tramite_consulta_tu_expediente(pexpediente character varying) RETURNS TABLE(numero_emision character varying, anio character varying, fecha_expediente character varying, rroexpediente character varying, tipo_documento character varying, nrodoc character varying, institucion character varying, remitente character varying, folios character varying, sumilla character varying, observacion character varying, oficina_atencion character varying, estado character varying, obsfinalizar character varying)
    LANGUAGE plpgsql
    AS $$
 DECLARE
   VDESC  VARCHAR(200)=NULL;
BEGIN
   RETURN QUERY SELECT 
R.NU_EMI ,R.NU_ANN 
,TO_CHAR(E.FE_EXP,'DD-MM-YYYY hh:mm:ss')::character varying FE_EXP
,E.NU_EXPEDIENTE  
,T.CDOC_DESDOC  
,R.DE_DOC_SIG 
,R.DE_ORI_DES  
,(CASE WHEN R.REMI_NU_DNI_EMI IS NOT NULL THEN (SELECT T.DENOM||' '||T.DEAPP||' '||T.DEAPM FROM IDOSGD.IDTANIRS T WHERE T.NULEM=R.REMI_NU_DNI_EMI)   
              WHEN R.REMI_CO_OTR_ORI_EMI IS NOT NULL THEN (SELECT O.DE_RAZ_SOC_OTR FROM IDOSGD.TDTR_OTRO_ORIGEN O WHERE O.CO_OTR_ORI=R.REMI_CO_OTR_ORI_EMI)
              ELSE ''
          END)::character varying as REMITE
, R.NU_FOLIOS::character varying as NU_FOLIOS
,R.DE_ASU  
,R.DE_OBS  
, COALESCE((SELECT DEP.DE_DEPENDENCIA FROM (SELECT DE.CO_DEP_DES,RE.NU_SEC_EXP,RE.NU_ANN 
				 FROM IDOSGD.TDTV_DESTINOS DE 
				INNER JOIN IDOSGD.TDTV_REMITOS RE ON DE.NU_ANN=RE.NU_ANN AND DE.NU_EMI=RE.NU_EMI 
				WHERE NOT RE.es_doc_emi	IN ('9','8','7','5')						
											ORDER BY DE.FE_USE_MOD DESC) D 
			   INNER JOIN IDOSGD.RHTM_DEPENDENCIA DEP ON DEP.CO_DEPENDENCIA=D.CO_DEP_DES 
                WHERE D.NU_SEC_EXP=E.NU_SEC_EXP AND D.NU_ANN=R.NU_ANN  limit 1),'') as OFI_ATENCION
,COALESCE((SELECT (CASE WHEN EST.CO_EST in ('0','1') THEN 'EN PROCESO' ELSE EST.DE_EST END) FROM (SELECT DE.CO_DEP_DES,RE.NU_SEC_EXP,RE.NU_ANN,ES_DOC_REC 
																								  FROM IDOSGD.TDTV_DESTINOS DE 
																								  INNER JOIN IDOSGD.TDTV_REMITOS RE ON DE.NU_ANN=RE.NU_ANN AND DE.NU_EMI=RE.NU_EMI
																								  ORDER BY DE.FE_USE_MOD DESC) D INNER JOIN IDOSGD.TDTR_ESTADOS EST ON EST.CO_EST=D.ES_DOC_REC AND EST.DE_TAB='TDTV_DESTINOS'  
                WHERE D.NU_SEC_EXP=E.NU_SEC_EXP AND D.NU_ANN=R.NU_ANN limit 1),'') as ESTADO_DOC
,COALESCE((SELECT D.DE_ANE FROM (SELECT DE.CO_DEP_DES,RE.NU_SEC_EXP,RE.NU_ANN,ES_DOC_REC,DE.DE_ANE 
									 FROM IDOSGD.TDTV_DESTINOS DE 
									 INNER JOIN IDOSGD.TDTV_REMITOS RE ON DE.NU_ANN=RE.NU_ANN AND DE.NU_EMI=RE.NU_EMI 
									 ORDER BY DE.FE_USE_MOD DESC) D WHERE D.NU_SEC_EXP=E.NU_SEC_EXP AND D.NU_ANN=R.NU_ANN limit 1),'') as OBSER_FINAL
         FROM IDOSGD.TDTC_EXPEDIENTE E
          INNER JOIN IDOSGD.TDTV_REMITOS R ON E.NU_ANN_EXP=R.NU_ANN AND E.NU_SEC_EXP=R.NU_SEC_EXP 
          INNER JOIN IDOSGD.SI_MAE_TIPO_DOC T ON T.CDOC_TIPDOC=R.CO_TIP_DOC_ADM
          WHERE NU_EXPEDIENTE=TRIM(pexpediente) AND R.TI_EMI IN ('04','02','03')
          ORDER BY R.NU_EMI;  

END;
$$;


ALTER FUNCTION idosgd.pk_sgd_tramite_consulta_tu_expediente(pexpediente character varying) OWNER TO postgres;

--
-- TOC entry 348 (class 1255 OID 21459)
-- Name: pk_sgd_tramite_consulta_tu_expediente2(character varying); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.pk_sgd_tramite_consulta_tu_expediente2(pexpediente character varying) RETURNS refcursor
    LANGUAGE plpgsql
    AS $$
 DECLARE ref1 refcursor := 'recordSets';
BEGIN
   open ref1  for  SELECT 
R.NU_EMI ,R.NU_ANN ,TO_CHAR(E.FE_EXP,'DD-MM-YYYY hh:mm:ss')::character varying FE_EXP
,E.NU_EXPEDIENTE ,T.CDOC_DESDOC  ,R.DE_DOC_SIG ,R.DE_ORI_DES  
,(CASE WHEN R.REMI_NU_DNI_EMI IS NOT NULL THEN (SELECT T.DENOM||' '||T.DEAPP||' '||T.DEAPM FROM IDOSGD.IDTANIRS T WHERE T.NULEM=R.REMI_NU_DNI_EMI)   
              WHEN R.REMI_CO_OTR_ORI_EMI IS NOT NULL THEN (SELECT O.DE_RAZ_SOC_OTR FROM IDOSGD.TDTR_OTRO_ORIGEN O WHERE O.CO_OTR_ORI=R.REMI_CO_OTR_ORI_EMI)
              ELSE ''
          END)::character varying as REMITE
, R.NU_FOLIOS::character varying as NU_FOLIOS
,R.DE_ASU  
,R.DE_OBS  
, COALESCE((SELECT DEP.DE_DEPENDENCIA FROM (SELECT DE.CO_DEP_DES,RE.NU_SEC_EXP,RE.NU_ANN 
											   FROM IDOSGD.TDTV_DESTINOS DE 
											   INNER JOIN IDOSGD.TDTV_REMITOS RE ON DE.NU_ANN=RE.NU_ANN AND DE.NU_EMI=RE.NU_EMI ORDER BY DE.FE_USE_MOD DESC) D 
			   INNER JOIN IDOSGD.RHTM_DEPENDENCIA DEP ON DEP.CO_DEPENDENCIA=D.CO_DEP_DES 
                WHERE D.NU_SEC_EXP=E.NU_SEC_EXP AND D.NU_ANN=R.NU_ANN  limit 1),'') as OFI_ATENCION
,COALESCE((SELECT (CASE WHEN EST.CO_EST in ('0','1') THEN 'EN PROCESO' ELSE EST.DE_EST END) FROM (SELECT DE.CO_DEP_DES,RE.NU_SEC_EXP,RE.NU_ANN,ES_DOC_REC 
																								  FROM IDOSGD.TDTV_DESTINOS DE 
																								  INNER JOIN IDOSGD.TDTV_REMITOS RE ON DE.NU_ANN=RE.NU_ANN AND DE.NU_EMI=RE.NU_EMI
																								  ORDER BY DE.FE_USE_MOD DESC) D INNER JOIN IDOSGD.TDTR_ESTADOS EST ON EST.CO_EST=D.ES_DOC_REC AND EST.DE_TAB='TDTV_DESTINOS'  
                WHERE D.NU_SEC_EXP=E.NU_SEC_EXP AND D.NU_ANN=R.NU_ANN limit 1),'') as ESTADO_DOC
,COALESCE((SELECT D.DE_ANE FROM (SELECT DE.CO_DEP_DES,RE.NU_SEC_EXP,RE.NU_ANN,ES_DOC_REC,DE.DE_ANE 
									 FROM IDOSGD.TDTV_DESTINOS DE 
									 INNER JOIN IDOSGD.TDTV_REMITOS RE ON DE.NU_ANN=RE.NU_ANN AND DE.NU_EMI=RE.NU_EMI 
									 ORDER BY DE.FE_USE_MOD DESC) D WHERE D.NU_SEC_EXP=E.NU_SEC_EXP AND D.NU_ANN=R.NU_ANN limit 1),'') as OBSER_FINAL
         FROM IDOSGD.TDTC_EXPEDIENTE E
          INNER JOIN IDOSGD.TDTV_REMITOS R ON E.NU_ANN_EXP=R.NU_ANN AND E.NU_SEC_EXP=R.NU_SEC_EXP 
          INNER JOIN IDOSGD.SI_MAE_TIPO_DOC T ON T.CDOC_TIPDOC=R.CO_TIP_DOC_ADM
          WHERE NU_EXPEDIENTE=TRIM(pexpediente) AND R.TI_EMI IN ('04','02','03')
          ORDER BY R.NU_EMI;  
  RETURN ref1;     
END;
$$;


ALTER FUNCTION idosgd.pk_sgd_tramite_consulta_tu_expediente2(pexpediente character varying) OWNER TO postgres;

--
-- TOC entry 358 (class 1255 OID 21460)
-- Name: pk_sgd_tramite_consulta_tu_expediente_seguimiento(character varying); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.pk_sgd_tramite_consulta_tu_expediente_seguimiento(pfiltro character varying) RETURNS TABLE(anio character varying, nroemision character varying, nrodestino character varying, tipodocumento character varying, nrodocumento character varying, emisor character varying, destinatario character varying, fechaemision character varying, estadodes character varying, obsdestino character varying)
    LANGUAGE plpgsql
    AS $$ 

BEGIN
   RETURN QUERY
   
SELECT   c.nu_ann  , c.nu_emi , c.nu_des::character varying nu_des  ,
idosgd.PK_SGD_DESCRIPCION_de_documento (b.co_tip_doc_adm) co_tip_doc_adm, 
                (CASE b.ti_emi WHEN '01' THEN b.nu_doc_emi || '-' || b.nu_ann || '-' || b.de_doc_sig 
                               WHEN '05' THEN b.nu_doc_emi || '-' || b.nu_ann || '-' || b.de_doc_sig ELSE COALESCE(b.de_doc_sig,'S/N')
					  END ) numero_doc, 
                substr(idosgd.PK_SGD_DESCRIPCION_DE_DEPENDENCIA(b.co_dep_emi), 1, 100)::character varying emisor_des 
                ,substring((CASE c.ti_des WHEN '01' THEN idosgd.PK_SGD_DESCRIPCION_de_dependencia(c.co_dep_des)
                                WHEN '02' THEN idosgd.PK_SGD_DESCRIPCION_de_proveedor(c.nu_ruc_des)
                                WHEN '03' THEN 'CIUDADANO - ' ||idosgd.PK_SGD_DESCRIPCION_ani_simil(c.nu_dni_des)
                                WHEN '04' THEN idosgd.PK_SGD_DESCRIPCION_otro_origen(c.co_otr_ori_des) ELSE ' '
							 END) , 1 , 100)::character varying destinatario_desc,
                TO_CHAR(b.fe_emi,'DD/MM/YYYY HH:MI:SS')::character varying fecha_emi,
				--c.nu_ann,c.nu_emi,c.nu_des nu_des,a.nu_ann_ref,a.nu_emi_ref,
               
                (CASE WHEN b.CO_TIP_DOC_ADM in ('011','012') THEN idosgd.PK_SGD_DESCRIPCION_ESTADOS (b.ES_DOC_EMI,'TDTV_REMITOS') 
				  ELSE (CASE WHEN c.ES_DOC_REC in ('0','1') THEN 'EN PROCESO' ELSE idosgd.PK_SGD_DESCRIPCION_ESTADOS (C.ES_DOC_REC,'TDTV_DESTINOS') END) END) estado_des
                --,C.DE_ANE "Descripcion",b.ES_DOC_EMI as "EstadoEmi"
				,c.DE_ANE OBSER
                FROM idosgd.tdtr_referencia a 
                INNER JOIN idosgd.tdtv_remitos b ON a.nu_ann = b.nu_ann and a.nu_emi = b.nu_emi
                INNER JOIN idosgd.tdtv_destinos c ON b.nu_ann = c.nu_ann  and b.nu_emi = c.nu_emi
                WHERE  b.es_eli = '0' 
                and b.es_doc_emi <> '9'
                and b.es_doc_emi <> '5'
                and b.es_doc_emi <> '7'
                and a.nu_ann_ref||a.nu_emi_ref||a.nu_des_ref = pfiltro;
				
END;
$$;


ALTER FUNCTION idosgd.pk_sgd_tramite_consulta_tu_expediente_seguimiento(pfiltro character varying) OWNER TO postgres;

