--
-- TOC entry 411 (class 1255 OID 21463)
-- Name: pk_sgd_tramite_crea_usuario(character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.pk_sgd_tramite_crea_usuario(pco_usuario character varying, pco_emp character varying, pnu_dni character varying, pin_ad character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  vnu_dni varchar(8);
  vde_nomemp varchar(200);
  vin boolean=true;
  verr varchar(400);
BEGIN
   BEGIN
      SELECT CEMP_NU_DNI ,  cemp_apepat||' '||cemp_apemat||' '||cemp_denom de_nombres 
        INTO vnu_dni , vde_nomemp 
        FROM IDOSGD.RHTM_PER_EMPLEADOS
       WHERE CEMP_CODEMP = pco_emp;
   EXCEPTION 
      when others then
         vin := false;
         verr := 'No Existe DNI --'||SUBSTR(SQLERRM,1,100);
   END;
   if vin then
      vin :=false;
      --Insertando Usuario
      BEGIN
         insert into IDOSGD.seg_usuarios1(cod_user,cdes_user,dfec_cre,cuser_cre,cuser_mod,dfec_mod,cclave,ccos_codcosto,cemp_codemp,es_usuario,in_ad)
         values(pco_usuario,vde_nomemp,current_timestamp,'ADM','ADM',CURRENT_TIMESTAMP,pnu_dni,NULL,pco_emp,'N',pin_ad);
         vin :=true;
      EXCEPTION 
         WHEN OTHERS THEN 
            vin :=false;
            verr := 'Error en Usuario --'||SUBSTR(SQLERRM,1,200);
      END;
      verr := idosgd.pk_sgd_tramite_crea_usuario_inserta('9', pco_usuario);
      if  verr <> 'OK' then
         verr :=  'Error en Asignar Usuario'||SUBSTR(verr,1,100);
         rollback;
      else
         verr := 'OK';
      end if;
   end if;    
   RETURN verr; 
 EXCEPTION 
         WHEN OTHERS THEN 
         verr := 'Error en pk_sgd_tramite_crea_usuario --'||SUBSTR(SQLERRM,1,200);
         RETURN verr;  
END;
$$;


ALTER FUNCTION idosgd.pk_sgd_tramite_crea_usuario(pco_usuario character varying, pco_emp character varying, pnu_dni character varying, pin_ad character varying) OWNER TO postgres;

--
-- TOC entry 430 (class 1255 OID 21464)
-- Name: pk_sgd_tramite_crea_usuario_inserta(character varying, character varying); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.pk_sgd_tramite_crea_usuario_inserta(pco_app character varying, pco_user character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
   c_opcion CURSOR FOR  
      SELECT pco_user co_user, 
             op.cod_aplica, 
             op.cod_opc, 
             op.es_habilitado 
        FROM IDOSGD.seg_user_aplica_opc op 
       WHERE op.cod_aplica = pco_app
         AND op.cod_user = 'BASICO' 
         AND op.es_habilitado = '1';  
   VRET varchar(400)='OK';
BEGIN
   BEGIN
      DELETE FROM IDOSGD.seg_user_aplica_opc op 
      WHERE op.cod_user = pco_user
      AND op.cod_aplica = pco_app; 
      DELETE FROM IDOSGD.seg_user_aplica op 
      WHERE cod_aplica = pco_app 
      AND cod_user = pco_user; 
      INSERT INTO IDOSGD.seg_user_aplica ( COD_USER, COD_APLICA, ES_ADMIN, ES_ACTIVO, FE_ACTIVO)
        SELECT pco_user, 
               ua.cod_aplica, 
               ua.es_admin,
               '1',
               current_timestamp 
          FROM IDOSGD.seg_user_aplica ua 
         WHERE ua.cod_aplica = pco_app 
           AND ua.cod_user = 'BASICO'; 
      FOR c IN c_opcion LOOP 
         BEGIN 
            INSERT INTO IDOSGD.seg_user_aplica_opc 
            VALUES 
              (c.co_user, 
               c.cod_aplica, 
               c.cod_opc, 
               c.es_habilitado); 
         EXCEPTION 
            WHEN OTHERS THEN 
            null;
         END; 
      END LOOP; 
      VRET := 'OK';
   EXCEPTION 
      WHEN OTHERS THEN 
      VRET := SQLERRM;
   END; 
   RETURN VRET;
END;
$$;


ALTER FUNCTION idosgd.pk_sgd_tramite_crea_usuario_inserta(pco_app character varying, pco_user character varying) OWNER TO postgres;

--
-- TOC entry 352 (class 1255 OID 21465)
-- Name: pk_sgd_tramite_pauditoria(character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.pk_sgd_tramite_pauditoria(ptable character varying, pdml character varying, ppk character varying, puser character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
 DECLARE
   cuserbd VARCHAR(50);
   cuseros VARCHAR(50);
   cip     VARCHAR(50);
   cpc     VARCHAR(50);
BEGIN
   SELECT session_user usuario,
          inet_server_addr() ip,
          current_database() pc,
          current_user usuario_os
     INTO cuserbd,
          cip,
          cpc,
          cuseros ;
     --FROM dual;
   INSERT INTO idosgd.tdts_auditoria
      (de_object,
       co_pktable,
       de_dml,
       fe_dml,
       co_us_dml,
       de_userbd,
       de_ippc,
       de_namepc,
       de_userpc)
   VALUES
      (ptable,
       ppk,
       pdml,
       now(),
       puser,
       cuserbd,
       cip,
       cpc,
       cuseros);
   RETURN NULL;
   
   
END;
$$;


