--
-- TOC entry 432 (class 1255 OID 21467)
-- Name: pk_sgd_tramite_pu_actualiza_guia_mp(character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.pk_sgd_tramite_pu_actualiza_guia_mp(pnu_ann character varying, pnu_emi character varying, pnu_des character varying, pes_doc_rec character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
	DECLARE
  	ntotal    NUMERIC(2);
   	ntotalrec NUMERIC(2);
  	c_recep_mp CURSOR FOR
      SELECT md.nu_ann_gui,
             md.nu_gui,
             md.nu_cor,
             re.nu_candes
        FROM IDOSGD.tdtc_guia_mp  mc,
             IDOSGD.tdtd_guia_mp  md,
             IDOSGD.tdtv_remitos  re,
             IDOSGD.tdtv_destinos de
       WHERE mc.nu_ann_gui = md.nu_ann_gui
         AND mc.nu_gui = md.nu_gui
         AND mc.es_gui_mp != '9'
         AND md.nu_ann_des = re.nu_ann
         AND md.nu_emi = re.nu_emi
         AND re.ti_emi NOT IN ('01', '05')
         AND re.nu_ann = de.nu_ann
         AND re.nu_emi = de.nu_emi
         AND md.nu_ann_des = de.nu_ann
         AND md.nu_emi = de.nu_emi
         AND md.nu_des = de.nu_des
         AND md.nu_ann_des = pnu_ann
         AND md.nu_emi = pnu_emi
         AND md.nu_des = CAST(pnu_des AS BIGINT);
BEGIN
   IF pes_doc_rec IN ('1', '0') THEN
      -- RECIBIDO, NO LEIDO
      FOR c IN c_recep_mp LOOP
         UPDATE IDOSGD.tdtd_guia_mp
            SET es_det_gui = case  when pes_doc_rec='1' then '1' when pes_doc_rec='0' then '0' END --RECIBIDO(RECIBIDO), NO LEIDO(GENERADO)
          WHERE nu_ann_gui = c.nu_ann_gui
            AND nu_gui = c.nu_gui
            AND nu_cor = c.nu_cor;
         BEGIN
            SELECT coalesce(COUNT(md.es_det_gui), 0) totales,
                   coalesce(COUNT(CASE WHEN md.es_det_gui='1' THEN 1 END), 0) recibidos
              INTO ntotal,
                   ntotalrec
              FROM IDOSGD.tdtc_guia_mp mc,
                   IDOSGD.tdtd_guia_mp md
             WHERE mc.nu_ann_gui = md.nu_ann_gui
               AND mc.nu_gui = md.nu_gui
               AND mc.es_gui_mp != '9'
               AND md.nu_ann_gui = c.nu_ann_gui
               AND md.nu_gui = c.nu_gui;
         EXCEPTION
            WHEN OTHERS THEN
               ntotal    := 0;
               ntotalrec := 0;
         END;
         IF ntotal = ntotalrec THEN
            UPDATE IDOSGD.tdtc_guia_mp 
               SET es_gui_mp = '1' -- recibido, completamente
             WHERE nu_ann_gui = c.nu_ann_gui
               AND nu_gui = c.nu_gui
               AND es_gui_mp != '9';
         ELSIF ntotalrec < ntotal AND
               ntotalrec > 0 THEN
            UPDATE IDOSGD.tdtc_guia_mp 
               SET es_gui_mp = '2' -- recibido, parcialmente
             WHERE nu_ann_gui = c.nu_ann_gui
               AND nu_gui = c.nu_gui
               AND es_gui_mp != '9';
         ELSIF ntotalrec = 0 THEN
            UPDATE IDOSGD.tdtc_guia_mp 
               SET es_gui_mp = '0' -- generado
             WHERE nu_ann_gui = c.nu_ann_gui
               AND nu_gui = c.nu_gui
               AND es_gui_mp != '9';
         END IF;
      END LOOP;
   END IF;

   RETURN NULL;
END;

$$;


ALTER FUNCTION idosgd.pk_sgd_tramite_pu_actualiza_guia_mp(pnu_ann character varying, pnu_emi character varying, pnu_des character varying, pes_doc_rec character varying) OWNER TO postgres;

--
-- TOC entry 428 (class 1255 OID 21468)
-- Name: pk_sgd_tramite_sp_act_calendario(timestamp without time zone, character varying); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.pk_sgd_tramite_sp_act_calendario(pfe_dia timestamp without time zone, pin_dia character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$
--*************************************************************************************************
-- Nombre         : SP_ACT_CALENDARIO
-- Autor          : Wiliams Cutipa
-- Version         : 1.0
-- Descripcion    : Procedimiento ACTUALIZAR O INSERTAR EL ESTADO DEL CALENDARIO.
-- Requerimientos :
-- Comentarios DBA:
-- Fecha       Modificado por  Revisado por    Visado por      Descripcion del Cambio
-- ==========  ==============  ==============  ==============  ==================================
--*************************************************************************************************

  BEGIN
         BEGIN
             INSERT INTO idosgd.SITM_CALENDARIO(FE_DIA,IN_DIA)
                  VALUES (PFE_DIA,PIN_DIA);
         EXCEPTION
           WHEN UNIQUE_VIOLATION THEN
                UPDATE idosgd.SITM_CALENDARIO SET IN_DIA = PIN_DIA
                WHERE   FE_DIA = PFE_DIA;
           WHEN OTHERS  THEN
              NULL;
         END;
	 RETURN(0);
  EXCEPTION
    WHEN OTHERS THEN
       NULL;
  END;
$$;


ALTER FUNCTION idosgd.pk_sgd_tramite_sp_act_calendario(pfe_dia timestamp without time zone, pin_dia character varying) OWNER TO postgres;

