--

CREATE FUNCTION idosgd.tdg_iotdtc_despacho() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE p_anexo smallint;
BEGIN
     BEGIN	
	  
	  IF NEW.CFLGEST = 'R' THEN
	   
		UPDATE IDOSGD.TDTV_DESTINOS SET OB_MSJ = NEW.VOBS
         WHERE  NU_EMI = NEW.VNUMREGSTD AND  NU_ANN = NEW.VANIOREGSTD AND  NU_RUC_DES = NEW.VRUCENTREC;
		 
		  INSERT INTO IDOSGD.TDTV_ANEXOS (
                        NU_ANN,     NU_EMI,     NU_ANE
			          , DE_DET, BL_DOC,   
                        DE_RUT_ORI, CO_USE_CRE, FE_USE_CRE,  NU_DES, FEULA)
          VALUES(     NEW.VANIOREGSTD, NEW.VNUMREGSTD, (SELECT   COALESCE(MAX(COALESCE(NU_ANE,0)),0) +1  FROM  IDOSGD.tdtv_anexos   WHERE NU_ANN =NEW.VANIOREGSTD  and  NU_EMI =NEW.VNUMREGSTD)
				    , 'CARGO.PDF', NEW.BCARSTDREC, 
                      'CARGO.PDF', 'IDOSGD', now(), 1, to_char(now(),'DDMMYYYY') );
		
	 END IF;
	   
	  
	   EXCEPTION
	     WHEN OTHERS THEN 
	       RAISE;
      END;
RETURN NEW;
END ;
$$;


