-- TOC entry 364 (class 1255 OID 21471)
-- Name: tdr_idtanirs(); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.tdr_idtanirs() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
	VCOUNT CHAR(1);
	BEGIN
		SELECT COUNT(1) INTO VCOUNT FROM idosgd.idtanirs WHERE NULEM=NEW.nulem;
		IF VCOUNT = '0' then
		   --if INSERTING then
			BEGIN
			
			  INSERT into IDOSGD.idtanirs
			  (select NULEM, UBDEP, UBPRV, UBDIS, DEAPP, DEAPM, DENOM
			  FROM idosgd.tdtx_ani_simil WHERE NULEM=NEW.nulem);
			  
			  EXCEPTION
				WHEN OTHERS THEN return null ;
			END;
		   --end if;
		ELSE
			BEGIN
			  UPDATE IDOSGD.idtanirs 
			  SET NULEM=NEW.NULEM,
				UBDEP=NEW.UBDEP,
				UBPRV=NEW.UBPRV,
				UBDIS=NEW.UBDIS,
				DEAPP=NEW.DEAPP,
				DEAPM=NEW.DEAPM,
				DENOM=NEW.DENOM
			  where NULEM=NEW.nulem;				
			END;
		END IF;
		RETURN NEW;
	END;
$$;


