--

CREATE FUNCTION idosgd.tdr_tdtc_expediente_in_up() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
-----------------------------------------------------------------------------------------------------
-- Nombre         : TDR_TDTC_EXPEDIENTE_IN_UP
-- Autor          : cshuan
-- Verion         : 1.0
-- Descripcion    : Establece los requisitos del expediente segun tipo de expediente.
-- Requerimientos : .
-- Ammedments   :
-- Cambio: se le ha modificado para qie utilize el package PK_SIA_PUBLICO
--   Fecha          Cambiado por       Revisado por           Visado por              Descripcion
--   ===========    ============     =================   ======================    ================
------------------------------------------------------------------------------------------------------
DECLARE
  -- LOCAL VARIABLES HERE
BEGIN
  IF (TG_OP = 'INSERT') THEN
     IF NEW.CO_PROCESO IS NOT NULL THEN
        --INSERTAR REQUISITOS DEL EXPEDIENTE EN TABLA TDTX_REQUISITO_EXPEDIENTE
        BEGIN
          INSERT INTO IDOSGD.TDTX_REQUISITO_EXPEDIENTE(
          NU_ANN_EXP,NU_SEC_EXP,
          COD_REQUISITO,COD_PROCESO,
          IN_OBLIGATORIO, NU_CORRELATIVO,
          IN_REQUISITO_OK,
          US_CREA_AUDI, US_MODI_AUDI)
          SELECT 
          NEW.NU_ANN_EXP, NEW.NU_SEC_EXP,
          COD_REQUISITO, COD_PROCESO,
          IN_OBLIGATORIO, NU_CORRELATIVO,
          CASE WHEN IN_OBLIGATORIO='0' THEN '1' ELSE '0' END,  
          'ADMIN', 'ADMIN'
          FROM IDOSGD.TDTX_REQUISITO_PROCESO
          WHERE COD_PROCESO=NEW.CO_PROCESO;                
        EXCEPTION WHEN OTHERS THEN
          NULL;
        END;        
     END IF;
  ELSIF (TG_OP = 'UPDATE') THEN
     /*IF NEW.CO_PROCESO IS NULL THEN
        DELETE FROM TDTX_REQUISITO_EXPEDIENTE
        WHERE NU_ANN_EXP=NEW.NU_ANN_EXP AND NU_SEC_EXP=NEW.NU_SEC_EXP;
     ELS*/IF NEW.CO_PROCESO!=OLD.CO_PROCESO THEN
        DELETE FROM IDOSGD.TDTX_REQUISITO_EXPEDIENTE
        WHERE NU_ANN_EXP=NEW.NU_ANN_EXP AND NU_SEC_EXP=NEW.NU_SEC_EXP;
        
        --INSERTAR REQUISITOS DEL EXPEDIENTE EN TABLA TDTX_REQUISITO_EXPEDIENTE
        BEGIN
          INSERT INTO IDOSGD.TDTX_REQUISITO_EXPEDIENTE(
          NU_ANN_EXP,NU_SEC_EXP,
          COD_REQUISITO,COD_PROCESO,
          IN_OBLIGATORIO, NU_CORRELATIVO,
          IN_REQUISITO_OK, 
          US_CREA_AUDI, US_MODI_AUDI)
          SELECT 
          NEW.NU_ANN_EXP, NEW.NU_SEC_EXP,
          COD_REQUISITO, COD_PROCESO,
          IN_OBLIGATORIO, NU_CORRELATIVO,
          CASE WHEN IN_OBLIGATORIO='0' THEN '1' ELSE '0' END,  
          'ADMIN', 'ADMIN'
          FROM IDOSGD.TDTX_REQUISITO_PROCESO
          WHERE COD_PROCESO=NEW.CO_PROCESO;                
        EXCEPTION WHEN OTHERS THEN
          NULL;
        END; 
     END IF;           
  END IF;
  RETURN NEW;
END;

$$;


