CREATE FUNCTION idosgd.tdr_tdtr_otro_origen() RETURNS trigger
    LANGUAGE plpgsql
    AS $$



DECLARE
    vin_existe char(1)= '1';
BEGIN
        BEGIN
         IF (TG_OP = 'UPDATE') THEN
             IF COALESCE(OLD.DE_APE_PAT_OTR,'0') <> COALESCE(NEW.DE_APE_PAT_OTR,'0') OR
                COALESCE(OLD.DE_APE_MAT_OTR,'0') <> COALESCE(NEW.DE_APE_MAT_OTR,'0') OR
                COALESCE(OLD.DE_NOM_OTR,'0') <> COALESCE(NEW.DE_NOM_OTR,'0') OR
                COALESCE(OLD.DE_RAZ_SOC_OTR,'0') <> COALESCE(NEW.DE_RAZ_SOC_OTR,'0') THEN

                IF (NEW.in_busca_texto = '00') THEN
                  NEW.in_busca_texto:='01';
                ELSE
                  NEW.in_busca_texto:='00';
                END IF;

             END IF;
          ELSIF (TG_OP = 'INSERT') THEN
             NEW.in_busca_texto:='00';
          END IF;
        EXCEPTION WHEN OTHERS THEN
              NULL;
	END;
        
RETURN NEW;
END;

$$;


