BEGIN
  BEGIN
	  IF (TG_OP = 'INSERT') THEN

	    INSERT INTO idosgd.TDTR_ARBOL_SEG (
	   NU_ANN,
	   NU_EMI,
	   NU_DES,
	   NU_ANN_REF,
	   NU_EMI_REF,
	   NU_DES_REF,
	   TI_EMI,
	   NU_ITEM
	   )
	   VALUES(
