--
-- TOC entry 415 (class 1255 OID 21478)
-- Name: tdr_tdtr_referencia_inup(); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.tdr_tdtr_referencia_inup() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

-----------------------------------------------------------------------------------------------------
-- Nombre          TDR_TDTR_REFERENCIA_INUP
-- Autor           William Cutipa
-- Verion          1.1
-- Descripcion     Inserta los Dependencias Resumen de los referencias.
-- Requerimientos  .
-- Ammedments     
-- Cambio se le ha modificado para qie utilize el package PK_SIA_PUBLICO
--   Fecha          Cambiado por       Revisado por           Visado por              Descripcion
--   ===========    ============     =================   ======================    ================
--   30-01-2007     Wiliams Cutipa                                                             Inserta a la tabla de tdtx_resumen_dep
------------------------------------------------------------------------------------------------------
DECLARE

  vco_dep      varchar(5);
  vco_emp_res  varchar(5);
  vco_dep_ref  varchar(5);
  vti_emi_ref  char(2);

BEGIN


  IF (TG_OP = 'INSERT') THEN
       begin

             select co_dep_emi, co_emp_res
              into vco_dep, vco_emp_res
             from idosgd.tdtv_remitos
             where nu_ann = NEW.nu_ann
              and nu_emi  = NEW.nu_emi;

             select CASE WHEN ti_emi='01' THEN co_dep_emi
                  WHEN ti_emi='02' THEN 'P'
                  WHEN ti_emi='03' THEN 'C'
                  WHEN ti_emi='04' THEN 'O'
                     WHEN ti_emi='05' THEN 'F' END AS co_dep_emi
                 ,ti_emi
              into vco_dep_ref, vti_emi_ref
             from idosgd.tdtv_remitos
             where nu_ann = NEW.nu_ann_ref
               and nu_emi  = NEW.nu_emi_ref;

            insert into idosgd.tdtx_resumen_dep(NU_ANN, CO_DEP, TI_TAB, TI_EMI, CO_EMP_RES,CO_DEP_REF)
           values(NEW.nu_ann,vco_dep,'R',vti_emi_ref,vco_emp_res, vco_dep_ref);
          exception when others then
                null;
        end;
  END IF;

   NEW.PK_EMI_EMI = NEW.NU_ANN||NEW.NU_EMI;
   NEW.PK_REF_EMI = NEW.NU_ANN_REF||NEW.NU_EMI_REF;

    /*EXCEPTION
       WHEN OTHERS THEN RETURN NULL;*/
 --      RAISE;

RETURN NEW;

END ;

$$;


ALTER FUNCTION idosgd.tdr_tdtr_referencia_inup() OWNER TO postgres;

