-- Name: tdr_tdtv_destinos_audi(); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.tdr_tdtv_destinos_audi() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ 
DECLARE
  cUSERBD varchar(50);
  cIPPC varchar(50);
  cNAMEPC varchar(50);
  cUSERPC   varchar(50);
  varReturn varchar;
BEGIN
  IF (TG_OP = 'DELETE') THEN
     varReturn := IDOSGD.PK_SGD_TRAMITE_PAUDITORIA('TDTV_DESTINOS','DELETE', OLD.NU_ANN|| OLD.NU_EMI|| OLD.NU_DES, OLD.CO_USE_MOD);
     varReturn := IDOSGD.PK_SGD_TRAMITE_PDATOSPC(cUSERBD,cIPPC,cNAMEPC,cUSERPC);
     INSERT INTO IDOSGD.TDTV_DESTINOS_HIS
     VALUES(
       OLD.nu_ann,
       OLD.nu_emi,
       OLD.nu_des,
       OLD.nu_cor_des,
       OLD.co_loc_des,
       OLD.co_dep_des,
       OLD.ti_des,
       OLD.nu_dni_des,
       OLD.co_emp_des,
       OLD.nu_ruc_des,
       OLD.co_otr_ori_des,
       OLD.co_pri,
       OLD.de_pro,
       OLD.co_exp,
       OLD.es_env_por_tra,
       OLD.es_rec_tra_desp,
       OLD.fe_rec_tra_desp,
       OLD.es_des,
       OLD.fe_des,
       OLD.es_rec_tra_dest,
       OLD.fe_rec_tra_dest,
       OLD.es_rep,
       OLD.fe_rep,
       OLD.co_emp_rec,
       OLD.es_doc_rec,
       OLD.fe_rec_doc,
       OLD.fe_der_doc,
       OLD.fe_arc_doc,
       OLD.de_asu_nue,
       OLD.nu_dia_ate_nue,
       OLD.nu_ann_ref,
       OLD.nu_emi_ref,
       OLD.nu_des_ref,
       OLD.co_mot,
       OLD.co_ubi_arc,
       OLD.fe_ent_ms,
       OLD.es_ent_ms,
       OLD.es_env_ms,
       OLD.es_eli,
       OLD.co_use_cre,
       OLD.fe_use_cre,
       OLD.co_use_mod,
       OLD.fe_use_mod,
       OLD.fe_ate_doc,
       OLD.de_ane,
       OLD.co_loc_des_pro,
       OLD.es_upd,
       OLD.es_ent_mp,
       OLD.es_mp_ent,
       OLD.fe_mp_ent,
       'DELETE',
      now(),
      cUSERBD,
      cIPPC,
      cNAMEPC,
      cUSERPC
     );
     RETURN OLD;
  END IF;
RETURN NEW;
END ;
$$;


ALTER FUNCTION idosgd.tdr_tdtv_destinos_audi() OWNER TO postgres;

--
-- TOC entry 397 (class 1255 OID 21484)
-- Name: tdr_tdtv_destinos_bandeja(); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.tdr_tdtv_destinos_bandeja() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

    IF (TG_OP = 'UPDATE') THEN
      IF NEW.ES_DOC_REC <> OLD.ES_DOC_REC OR NEW.co_emp_rec <> OLD.co_emp_rec THEN
         BEGIN
		IF(SELECT COUNT(nu_ann) FROM IDOSGD.tdtv_bandeja_rec WHERE nu_ann = NEW.nu_ann AND nu_emi = NEW.nu_emi AND nu_des = NEW.nu_des)>0 THEN
			BEGIN
				UPDATE IDOSGD.tdtv_bandeja_rec
				      SET   co_emp_rec = NEW.co_emp_rec , es_doc_rec = NEW.es_doc_rec
				      WHERE nu_ann = NEW.nu_ann 
					AND nu_emi = NEW.nu_emi
					AND nu_des = NEW.nu_des;
			END;
		ELSE
			BEGIN
				INSERT INTO IDOSGD.tdtv_bandeja_rec(nu_ann, nu_emi, nu_des, ti_des, co_dep_des, co_emp_des, es_doc_rec, co_emp_rec, es_doc_emi  )
				VALUES(NEW.nu_ann,NEW.nu_emi,NEW.nu_des,NEW.ti_des,NEW.co_dep_des,NEW.co_emp_des,NEW.es_doc_rec, NEW.co_emp_rec,'0');

				RETURN NEW;
				EXCEPTION WHEN OTHERS THEN
				NULL;						
			END;
		END IF;   
        END;
      END IF;
      
      IF NEW.co_etiqueta_rec <> OLD.co_etiqueta_rec THEN
         BEGIN
		IF(SELECT COUNT(nu_ann) FROM IDOSGD.tdtv_bandeja_rec WHERE nu_ann = NEW.nu_ann AND nu_emi = NEW.nu_emi AND nu_des = NEW.nu_des)>0 THEN
			BEGIN
				UPDATE IDOSGD.tdtv_bandeja_rec
				SET   co_etiqueta_rec = NEW.co_etiqueta_rec
				WHERE nu_ann = NEW.nu_ann 
				AND nu_emi = NEW.nu_emi
				AND nu_des = NEW.nu_des;
			END;
		ELSE
			BEGIN
				
				INSERT INTO IDOSGD.tdtv_bandeja_rec(nu_ann, nu_emi, nu_des, ti_des, co_dep_des, co_emp_des, es_doc_rec ,co_emp_rec, co_etiqueta_rec , es_doc_emi)
				values(NEW.nu_ann,NEW.nu_emi,NEW.nu_des,NEW.ti_des,NEW.co_dep_des,NEW.co_emp_des,NEW.es_doc_rec,NEW.co_emp_rec, NEW.co_etiqueta_rec,'0');
				RETURN NEW;
				EXCEPTION WHEN OTHERS THEN
				NULL;
			END;
		END IF;			
         END;
      END IF;

    ELSIF (TG_OP = 'INSERT') THEN
	BEGIN
             INSERT INTO IDOSGD.tdtv_bandeja_rec(nu_ann, nu_emi, nu_des, ti_des, co_dep_des, co_emp_des, es_doc_rec,co_etiqueta_rec , es_doc_emi )
                 values(NEW.nu_ann,NEW.nu_emi,NEW.nu_des,NEW.ti_des,NEW.co_dep_des,NEW.co_emp_des,NEW.es_doc_rec,NEW.co_etiqueta_rec ,'5');
                 RETURN NEW;
		EXCEPTION WHEN OTHERS THEN
                NULL;
        END;       
    ELSIF (TG_OP = 'DELETE') THEN
         BEGIN
              DELETE FROM IDOSGD.tdtv_bandeja_rec
              WHERE nu_ann = OLD.nu_ann 
                AND nu_emi = OLD.nu_emi
                AND nu_des = OLD.nu_des;
                RETURN OLD;
          EXCEPTION WHEN OTHERS THEN
               NULL;
         END;
  END IF;
RETURN NEW;
END ;
$$;


ALTER FUNCTION idosgd.tdr_tdtv_destinos_bandeja() OWNER TO postgres;

--
-- TOC entry 373 (class 1255 OID 21485)
-- Name: tdr_tdtv_destinos_in(); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.tdr_tdtv_destinos_in() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
-----------------------------------------------------------------------------------------------------
-- Nombre         : TDR_TDTV_DESTINOS_IN
-- Autor          : WCONDORI
-- Verion         : 1.4
-- Descripcion    : Crea un Registro de Movimiento de Estados de la Tabla de Destinos.
-- Requerimientos : .
-- Ammedments   :
-- Cambio: se le ha modificado para qie utilize el package PK_SIA_PUBLICO
--   Fecha          Cambiado por       Revisado por           Visado por              Descripcion
--   ===========    ============     =================   ======================    ================
------------------------------------------------------------------------------------------------------
DECLARE
   vco_doc     varchar(3);
   vco_dep_ref varchar(5);
   vti_emi_ref char(2);

     PTI_APP VARCHAR(50);
     PIP_PC VARCHAR(50);
     PNO_PC VARCHAR(50);
     PUS_PC VARCHAR(50);
     PUS_APP VARCHAR(50);
     PNU_SES VARCHAR(50);

BEGIN
	
	
	
    IF (TG_OP = 'INSERT') THEN
           BEGIN
               UPDATE IDOSGD.TDTV_REMITOS SET NU_CANDES = NEW.NU_DES
                  WHERE NU_ANN = NEW.NU_ANN
                    AND NU_EMI = NEW.NU_EMI;
               EXCEPTION
                 WHEN OTHERS THEN  NULL;
           END;
-- Para Resumen de Dependencias y Documentos--
      BEGIN
               select 
			
		 CASE WHEN ti_emi='01' THEN co_dep_emi
	         WHEN ti_emi='02' THEN 'P'
	         WHEN ti_emi='03' THEN 'C'
	         WHEN ti_emi='04' THEN 'O'
		 WHEN ti_emi='05' THEN 'F'
		 END AS co_dep_emi,
                 ti_emi,
                 CO_TIP_DOC_ADM
                into vco_dep_ref, vti_emi_ref , vco_doc
                from IDOSGD.tdtv_remitos
                   WHERE NU_ANN = NEW.NU_ANN
                     AND NU_EMI = NEW.NU_EMI;

          -- Insertando Resumen de Documentos
          BEGIN
                  insert into IDOSGD.tdtx_resumen_doc(NU_ANN, CO_DEP, TI_TAB, CO_DOC)
                 values( NEW.nu_ann, NEW.co_dep_des,'D',vco_doc);
          EXCEPTION WHEN OTHERS THEN 
                NULL;
          END;
          -- Insertando Resumen de Dependencias
          BEGIN
           if   NEW.TI_DES <> '01' then
                 vti_emi_ref   =   NEW.TI_DES;
          end if;

           insert into IDOSGD.tdtx_resumen_dep(NU_ANN, CO_DEP, TI_TAB, TI_EMI, CO_EMP_RES,CO_DEP_REF)
           values(  NEW.nu_ann,vco_dep_ref,'D',vti_emi_ref,   NEW.co_emp_des,
                   CASE  WHEN NEW.TI_DES='01' THEN NEW.co_dep_des
						 WHEN NEW.TI_DES='02' THEN 'P'
						 WHEN NEW.TI_DES='03' THEN 'C'
						 WHEN NEW.TI_DES='04' THEN 'O'
						 WHEN NEW.TI_DES='05' THEN 'F'
		 END );

           EXCEPTION WHEN OTHERS THEN		   
            NULL;
           END;

       EXCEPTION WHEN OTHERS THEN	    
        NULL;
       END;
  END IF;
RETURN NEW;
END ;
$$;


ALTER FUNCTION idosgd.tdr_tdtv_destinos_in() OWNER TO postgres;

--
-- TOC entry 399 (class 1255 OID 21486)
-- Name: tdr_tdtv_destinos_in_up(); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.tdr_tdtv_destinos_in_up() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
-----------------------------------------------------------------------------------------------------
-- Nombre         : TDR_TDTV_DESTINOS_IN_UP
-- Autor          : William Cutipa
-- Verion         : 2.0
-- Descripcion    : Controlde Errores del la tabla de Destinos.
-- Requerimientos : .
-- Ammedments   :
-- Cambio: se le ha agregado la funcion VER_INHABIL
--   Fecha          Cambiado por       Revisado por           Visado por              Descripcion
--   ===========    ============     =================   ======================    ================
--   08-09-2006     Wiliams Cutipa                                        Cambio del co_gru
--   22-10-2008     Wiliams Cutipa                                        Modificacion en el SELECT R.CO_GRU
------------------------------------------------------------------------------------------------------
declare
  co_gru char(1);
 
  cMsg varchar(200);
BEGIN

   select r.co_gru into co_gru
     from idosgd.tdtv_remitos r
    where r.nu_ann=new.nu_ann
      and r.nu_emi=new.nu_emi;

   /**Para Administrativos**/
   if co_gru <>'4' then
   /**Reniec**/
     if new.ti_des = '01' then
       if new.co_dep_des is null then
          RAISE EXCEPTION '%' , $1;
       end if;
       if new.co_loc_des is null then
          RAISE EXCEPTION '%' , $1;
       end if;
       if new.co_mot is null then
          RAISE EXCEPTION '%' , $1;
       end if;
       if new.co_pri is null then
          RAISE EXCEPTION '%' , $1;
       end if;
     /**Proveedor**/
     elsif new.ti_des = '02' then
       if new.nu_ruc_des is null then
          RAISE EXCEPTION '%' , $1;
       end if;
     /**Ciudadano**/
     elsif new.ti_des = '03' then
       if new.nu_dni_des is null then
          RAISE EXCEPTION '%' , $1;
       end if;
     /**Otro**/
     elsif new.ti_des = '04' then
       if new.co_otr_ori_des is null then
          RAISE EXCEPTION '%' , $1;
       end if;
     end if;
   end if;
   /**Para procesos**/
   if co_gru ='4' then
     if new.co_loc_des_pro is null then
        RAISE EXCEPTION '%' , $1;
     end if;
     if new.co_dep_des is null then
        RAISE EXCEPTION '%' , $1;
     end if;
     if new.co_pri is null then
        RAISE EXCEPTION '%' , $1;
     end if;
   end if;

RETURN NEW;
END ;
$_$;


ALTER FUNCTION idosgd.tdr_tdtv_destinos_in_up() OWNER TO postgres;

