--
-- TOC entry 448 (class 1255 OID 21490)
-- Name: tdr_tdtv_remitos_resumen(); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.tdr_tdtv_remitos_resumen() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
	vnu_exp VARCHAR(70)=null;
	vco_pro VARCHAR(4)=null;
  BEGIN
	IF (TG_OP = 'UPDATE' ) THEN
	   -- Verificando el Estado del Documento
         IF NEW.ES_DOC_EMI!=OLD.ES_DOC_EMI THEN
            BEGIN
                UPDATE idosgd.TDTX_REMITOS_RESUMEN SET ES_DOC_EMI = NEW.ES_DOC_EMI
                WHERE NU_ANN=NEW.NU_ANN
                AND NU_EMI=NEW.NU_EMI;
            EXCEPTION WHEN OTHERS THEN
               NULL;
            END;
            BEGIN
                update idosgd.tdtv_bandeja_rec set es_doc_emi = NEW.ES_DOC_EMI
                where nu_ann =NEW.NU_ANN
                and nu_emi = NEW.NU_EMI;
             EXCEPTION WHEN OTHERS THEN
                   NULL;
             END;
         END IF;
		-- Verificamos Datos Variantes
         IF coalesce(NEW.nu_doc_emi,'0')!=coalesce(OLD.nu_doc_emi,'0') OR coalesce(NEW.de_doc_sig,'0')!=coalesce(OLD.de_doc_sig,'0')  THEN
            BEGIN
                UPDATE idosgd.TDTX_REMITOS_RESUMEN SET
                       nu_doc = substr(CASE NEW.ti_emi WHEN '01' THEN  NEW.nu_doc_emi || '-' || NEW.nu_ann || '-' || NEW.de_doc_sig WHEN '05' THEN  NEW.nu_doc_emi || '-' || NEW.nu_ann || '-' || NEW.de_doc_sig ELSE NEW.de_doc_sig END,1,50)
                WHERE NU_ANN=NEW.NU_ANN
                AND NU_EMI=NEW.NU_EMI;
             EXCEPTION WHEN OTHERS THEN
               NULL;
            END;
         END IF;
		-- Verificando los demas datos
         IF NEW.ti_emi!=OLD.ti_emi OR NEW.co_dep_emi!=OLD.co_dep_emi OR NEW.co_emp_emi!=OLD.co_emp_emi  THEN
            BEGIN
                UPDATE idosgd.TDTX_REMITOS_RESUMEN SET
                       ti_emi = NEW.ti_emi,
                       co_dep_emi_ref =  CASE NEW.ti_emi WHEN '01' THEN  NEW.co_dep_emi WHEN '02' THEN  'P' WHEN '03' THEN  'C' WHEN '04' THEN  'O' WHEN '05' THEN 'F' END,
                       co_emp_emi = NEW.co_emp_emi
                WHERE NU_ANN=NEW.NU_ANN
                AND NU_EMI=NEW.NU_EMI;
            EXCEPTION WHEN OTHERS THEN
                NULL;
            END;
         END IF; 
		-- Verificamos el Expediente
         IF (coalesce(NEW.NU_SEC_EXP,'0') = COALESCE(OLD.NU_SEC_EXP,'0'))  THEN
            BEGIN
                BEGIN
                  select co_proceso,nu_expediente
                  into vco_pro ,vnu_exp
                  from idosgd.tdtc_expediente
                  where nu_ann_exp = NEW.NU_ANN_EXP
                  and nu_sec_exp = NEW.NU_SEC_EXP;
                  EXCEPTION WHEN OTHERS THEN
                    vnu_exp := null;
                    vco_pro := null;
		  END;

               UPDATE idosgd.TDTX_REMITOS_RESUMEN SET
                       nu_expediente = vnu_exp,
                       co_proceso_exp = vco_pro
                WHERE NU_ANN=NEW.NU_ANN
                AND NU_EMI=NEW.NU_EMI;
                EXCEPTION WHEN OTHERS THEN
                  NULL;
            END;
         END IF; 		 
    ELSIF (TG_OP = 'INSERT') THEN
		BEGIN
			IF (NEW.NU_ANN_EXP IS NOT NULL AND NEW.NU_SEC_EXP IS NOT NULL)  THEN
				BEGIN
					BEGIN
						select co_proceso,nu_expediente
						into vco_pro ,vnu_exp
						from idosgd.tdtc_expediente
						where nu_ann_exp = NEW.NU_ANN_EXP
						and nu_sec_exp = NEW.NU_SEC_EXP;					
					    EXCEPTION WHEN OTHERS THEN
						 vnu_exp := null;
						 vco_pro := null;
					END;
				  EXCEPTION WHEN OTHERS THEN
                                      NULL;
				END;
			END IF;

           insert into idosgd.TDTX_REMITOS_RESUMEN(
                nu_ann,
                nu_emi,
                ti_emi,
                es_doc_emi,
                co_dep_emi_ref,
                co_emp_emi,
                nu_doc,
                nu_expediente,
                co_proceso_exp
                )
             values(
                NEW.nu_ann,
                NEW.nu_emi,
                NEW.ti_emi,
                NEW.es_doc_emi,
                CASE NEW.ti_emi
                         WHEN '01' THEN  NEW.co_dep_emi
                         WHEN '02' THEN  'P'
                         WHEN '03' THEN  'C'
                         WHEN '04' THEN  'O'
                         WHEN '05' THEN  'F' END,
                NEW.co_emp_emi,
                substr(CASE NEW.ti_emi
                       WHEN '01' THEN  
							COALESCE(NEW.nu_doc_emi,'') || '-' || COALESCE(NEW.nu_ann,'') || '-' || COALESCE(NEW.de_doc_sig,'')
                       WHEN '05' THEN  
							COALESCE(NEW.nu_doc_emi,'') || '-' || COALESCE(NEW.nu_ann,'') || '-' || COALESCE(NEW.de_doc_sig,'')
                             ELSE NEW.de_doc_sig END,1,50),
                vnu_exp,
                vco_pro
             );
         EXCEPTION WHEN OTHERS THEN
                NULL;
        END;
	END IF; 
	RETURN NEW;
END;
$$;


ALTER FUNCTION idosgd.tdr_tdtv_remitos_resumen() OWNER TO postgres;

