--
-- TOC entry 414 (class 1255 OID 21492)
-- Name: tdr_tdtv_remitos_text(); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.tdr_tdtv_remitos_text() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    vin_cambio char(1):='0';
    VDE_OTRO_EMI VARCHAR(200):= NULL;
BEGIN

    -- Para el caso de Mesa de Partes

     BEGIN
       IF (TG_OP = 'UPDATE') THEN

           if NEW.ti_emi != OLD.ti_emi THEN
              IF NEW.ti_emi = '02' OR NEW.ti_emi = '03' OR NEW.ti_emi = '04'  THEN
                vin_cambio := '2';
              END IF;
           end if;


           IF COALESCE(OLD.DE_ASU,'0') <> COALESCE(NEW.DE_ASU,'0') OR
              COALESCE(OLD.DE_ORI_EMI,'0') <> COALESCE(NEW.DE_ORI_EMI,'0') OR
              COALESCE(OLD.DE_ORI_DES,'0') <> COALESCE(NEW.DE_ORI_DES,'0') THEN
                vin_cambio := '1';
           END IF;
        ELSIF (TG_OP = 'INSERT')THEN
            vin_cambio := '1';
            IF NEW.ti_emi = '02' OR NEW.ti_emi = '03' OR NEW.ti_emi = '04'  THEN
              vin_cambio := '2';
            END IF;
        END IF;

       if vin_cambio = '2' then
         begin
           IF NEW.ti_emi = '02' then
               SELECT A.CPRO_RAZSOC
               INTO   VDE_OTRO_EMI
               FROM   IDOSGD.LG_PRO_PROVEEDOR A
               WHERE  A.CPRO_RUC = NEW.nu_ruc_emi;
           elsif NEW.ti_emi = '03' then
             SELECT SUBSTR(RTRIM(DEAPP)||' '||RTRIM(DEAPM)||' '||RTRIM(DENOM),1,200)
             INTO   VDE_OTRO_EMI
             FROM   IDOSGD.TDTX_ANI_SIMIL
             WHERE  NULEM=NEW.nu_dni_emi;
           elsif NEW.ti_emi = '04' then
             SELECT COALESCE(A.DE_RAZ_SOC_OTR,' ')||' '|| COALESCE(A.DE_APE_PAT_OTR,' ') ||' '||COALESCE(A.DE_APE_MAT_OTR,' ')||' '||COALESCE(A.DE_NOM_OTR,' ')
             INTO   VDE_OTRO_EMI
             FROM   IDOSGD.TDTR_OTRO_ORIGEN A
             WHERE  A.CO_OTR_ORI = NEW.co_otr_ori_emi;
           end if;
         exception when others then
             VDE_OTRO_EMI := NULL;
         end;

         NEW.DE_ORI_EMI := VDE_OTRO_EMI;
         vin_cambio := '1';
       end if;

       if vin_cambio = '1' then
          IF NEW.in_busca_texto = '0' THEN
            NEW.in_busca_texto:='1';
          ELSE
            NEW.in_busca_texto:='0';
          END IF;
       end if;

      EXCEPTION WHEN OTHERS THEN
            NULL;
      END;
RETURN NEW;
END;
$$;


ALTER FUNCTION idosgd.tdr_tdtv_remitos_text() OWNER TO postgres;

