--
-- TOC entry 357 (class 1255 OID 21495)
-- Name: tdtv_remitos_audi(); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.tdtv_remitos_audi() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
 
DECLARE
  cUSERBD varchar(50);
  cIPPC varchar(50);
  cNAMEPC varchar(50);
  cUSERPC   varchar(50);
  varReturn varchar;

BEGIN
  IF (TG_OP = 'DELETE') THEN
     varReturn := IDOSGD.PK_SGD_TRAMITE_PAUDITORIA('TDTV_REMITOS','DELETE', OLD.NU_ANN|| OLD.NU_EMI, OLD.CO_USE_MOD);
     varReturn := IDOSGD.PK_SGD_TRAMITE_PDATOSPC(cUSERBD,cIPPC,cNAMEPC,cUSERPC);
     INSERT INTO IDOSGD.TDTV_REMITOS_HIS
     VALUES(
      OLD.nu_ann,
       OLD.nu_emi,
       OLD.nu_cor_emi,
       OLD.co_loc_emi,
       OLD.co_dep_emi,
       OLD.ti_emi,
       OLD.nu_dni_emi,
       OLD.co_emp_emi,
       OLD.nu_ruc_emi,
       OLD.co_otr_ori_emi,
       OLD.fe_emi,
       OLD.nu_doc,
       OLD.co_gru,
       OLD.de_asu,
       OLD.es_doc_emi,
       OLD.nu_dia_ate,
       OLD.de_obs,
       OLD.fe_arc,
       OLD.ti_cap,
       OLD.es_eli,
       OLD.co_use_cre,
       OLD.fe_use_cre,
       OLD.co_use_mod,
       OLD.fe_use_mod,
       OLD.co_tip_doc_adm,
       OLD.co_tip_doc_pro,
       OLD.de_ane,
       OLD.co_loc_emi_pro,
       OLD.es_upd,
       OLD.co_emp_res,
      'DELETE',
      now(),
      cUSERBD,
      cIPPC,
      cNAMEPC,
      cUSERPC
     );

  END IF;
RETURN NEW;
END ;
$$;


