--
-- TOC entry 393 (class 1255 OID 21500)
-- Name: tr_rhtm_dependencia_encargos(); Type: FUNCTION; Schema: idosgd; Owner: postgres
--

CREATE FUNCTION idosgd.tr_rhtm_dependencia_encargos() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE 	
	rcemi record;
	rcdes record;
	cemi CURSOR FOR SELECT nu_ann, nu_emi
			FROM idosgd.tdtv_remitos
			WHERE co_dep_emi = OLD.co_dependencia and co_emp_emi = OLD.co_empleado and es_doc_emi in ('5','7');
			
	cdes CURSOR FOR SELECT  b.nu_ann, b.nu_emi , b.nu_des
			FROM idosgd.tdtv_remitos a , idosgd.tdtv_destinos b
			WHERE a.nu_ann = b.nu_ann and a.nu_emi = b.nu_emi and a.es_doc_emi in ('5','7') and b.co_dep_des = OLD.co_dependencia and b.co_emp_des = OLD.co_empleado;

	BEGIN
		IF (TG_OP = 'UPDATE' ) THEN
			BEGIN
				IF NEW.co_empleado <> OLD.co_empleado THEN
					BEGIN
					FOR rcemi IN cemi LOOP
						UPDATE idosgd.tdtv_remitos set co_emp_emi = NEW.co_empleado
							WHERE nu_ann = rcemi.nu_ann
							AND nu_emi = rcemi.nu_emi;
						
					END LOOP;
					
					FOR rcdes IN cemi LOOP
						UPDATE idosgd.tdtv_destinos set co_emp_des = NEW.co_empleado
							WHERE nu_ann = rcdes.nu_ann
							AND nu_emi = rcdes.nu_emi
							AND nu_des = rcdes.nu_des;
					END LOOP;
					EXCEPTION WHEN OTHERS THEN
						NULL;
					END;
				END IF;
			END;
		END IF;
		RETURN NEW;
	END;	
$$;


ALTER FUNCTION idosgd.tr_rhtm_dependencia_encargos() OWNER TO postgres;

