    LANGUAGE plpgsql
    AS $$

-----------------------------------------------------------------------------------------------------
-- Nombre         : TTR_TDTR_CALENDARIO
-- Autor          : William Cutipa
-- Verion         : 1.0
-- Descripcion    : Actualiza a la tabla de SITM_CALENDARIO
