--   ===========    ============     =================   ======================    ================
--   24-10-2008     Wiliams Cutipa                                                    Creacion de Trigger
------------------------------------------------------------------------------------------------------

DECLARE
  varReturn integer;
BEGIN
   BEGIN
	   varReturn:=idosgd.SP_ACT_CALENDARIO(NEW.FE_LUN, NEW.ES_LUN);
	   varReturn:=idosgd.SP_ACT_CALENDARIO(NEW.FE_MAR, NEW.ES_MAR);
