	   varReturn:=idosgd.SP_ACT_CALENDARIO(NEW.FE_JUE, NEW.ES_JUE);
	   varReturn:=idosgd.SP_ACT_CALENDARIO(NEW.FE_VIE, NEW.ES_VIE);
	   varReturn:=idosgd.SP_ACT_CALENDARIO(NEW.FE_SAB, NEW.ES_SAB);
	   varReturn:=idosgd.SP_ACT_CALENDARIO(NEW.FE_DOM, NEW.ES_DOM);
	exception when others then
