CREATE FUNCTION idosgd.tr_tdtv_remitos_est() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN

     IF NEW.ES_DOC_EMI!= OLD.ES_DOC_EMI AND NEW.ES_DOC_EMI ='5' THEN

      UPDATE IDOSGD.TDTV_PERSONAL_VB SET  IN_VB = '0',
                          FE_VB = NULL,
