--

CREATE VIEW idosgd.conpav_rh_per_empleados AS
 SELECT cemp_codemp,
    (((((cemp_apepat)::text || ' '::text) || (cemp_apemat)::text) || ' '::text) || (cemp_denom)::text) AS fullname,
    cemp_apepat,
    cemp_apemat,
    cemp_denom AS cemp_prinom,
    NULL::text AS femp_fecalt,
    cemp_tipsex,
    NULL::text AS cban_codban,
    NULL::text AS banco,
    cemp_co_cargo AS ccar_codcar,
    ( SELECT rhtm_cargos.ccar_descar
           FROM idosgd.rhtm_cargos
          WHERE ((rhtm_cargos.ccar_co_cargo)::text = (rhtm_per_empleados.cemp_co_cargo)::text)) AS cargo,
    cemp_nu_dni AS cemp_dniemp,
    NULL::text AS ccos_codcosto,
    NULL::text AS cchijo,
    NULL::text AS ccpadre,
    NULL::text AS decchijo,
    NULL::text AS deccpadre,
    cemp_indbaj
   FROM idosgd.rhtm_per_empleados;


